import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import {
  AlertTriangle,
  ArrowUpRight,
  ChevronDown,
  CircleHelp,
  Clock3,
  Crosshair,
  Filter,
  Layers3,
  List,
  LocateFixed,
  Map as MapIcon,
  MapPin,
  RefreshCw,
  RotateCcw,
  Search,
  Share2,
  ShieldCheck,
  SlidersHorizontal,
  Waves,
  X,
} from 'lucide-react'
import { MapView } from './MapView'
import { Timeline } from './Timeline'
import {
  DEFAULT_FILTERS,
  FEEDS,
  RANGE_LABELS,
  cacheFeed,
  depthBand,
  filterEvents,
  formatDateTime,
  formatDepth,
  formatMagnitude,
  formatRelativeTime,
  formatUtc,
  loadCachedFeed,
  magnitudeLabel,
  parseUrlState,
  percentileContext,
  writeUrlState,
} from './data'
import type { EarthquakeFeature, EarthquakeFeed, FilterState, MapBounds, TimeRange } from './types'

const initialState = parseUrlState()

function updateFilter<K extends keyof FilterState>(filters: FilterState, key: K, value: FilterState[K]): FilterState {
  return { ...filters, [key]: value }
}

function statusCopy(event: EarthquakeFeature) {
  if (event.properties.alert === 'red') return 'Red impact alert issued by USGS models'
  if (event.properties.alert === 'orange') return 'Orange impact alert issued by USGS models'
  if (event.properties.alert === 'yellow') return 'Yellow impact alert issued by USGS models'
  if (event.properties.alert === 'green') return 'Green impact alert issued by USGS models'
  if ((event.properties.mag ?? 0) >= 6) return 'Large magnitude; impact depends on depth, distance, and local conditions'
  if ((event.properties.mag ?? 0) >= 4.5) return 'Notable event in the current activity window'
  return 'Routine event within the current activity window'
}

function TimeTabs({ value, onChange }: { value: TimeRange; onChange: (range: TimeRange) => void }) {
  return (
    <div className="time-tabs" aria-label="Activity period">
      {(Object.keys(RANGE_LABELS) as TimeRange[]).map((range) => (
        <button
          key={range}
          type="button"
          className={value === range ? 'is-active' : ''}
          aria-pressed={value === range}
          onClick={() => onChange(range)}
        >
          {range === 'hour' ? '1H' : range === 'day' ? '24H' : range === 'week' ? '7D' : '30D'}
          <span>{RANGE_LABELS[range]}</span>
        </button>
      ))}
    </div>
  )
}

interface FilterPanelProps {
  filters: FilterState
  onChange: (filters: FilterState) => void
  resultCount: number
  totalCount: number
  onClose?: () => void
}

function FilterPanel({ filters, onChange, resultCount, totalCount, onClose }: FilterPanelProps) {
  return (
    <div className="filter-panel">
      <div className="filter-panel-heading">
        <div>
          <p className="eyebrow">Refine the field</p>
          <h2>Filters</h2>
        </div>
        {onClose && <button className="icon-button" type="button" onClick={onClose} aria-label="Close filters"><X /></button>}
      </div>

      <label className="field search-field">
        <span>Place or region</span>
        <div><Search aria-hidden="true" /><input value={filters.query} onChange={(event) => onChange(updateFilter(filters, 'query', event.target.value))} placeholder="Japan, Alaska, ridge…" /></div>
        <small>Searches locations named by USGS in the loaded feed.</small>
      </label>

      <fieldset className="field magnitude-filter">
        <legend>Minimum magnitude <button className="term-help" type="button" title="Magnitude measures energy released at the source. It does not predict damage."><CircleHelp /><span className="sr-only">About magnitude</span></button></legend>
        <div className="magnitude-value">M {filters.minMagnitude.toFixed(1)}+</div>
        <input type="range" min="-1" max="7" step="0.5" value={filters.minMagnitude} onChange={(event) => onChange(updateFilter(filters, 'minMagnitude', Number(event.target.value)))} aria-label={`Minimum magnitude ${filters.minMagnitude.toFixed(1)}`} />
        <div className="range-labels"><span>All</span><span>4.0</span><span>7.0+</span></div>
      </fieldset>

      <fieldset className="field">
        <legend>Depth <button className="term-help" type="button" title="Depth is how far below the surface an earthquake begins. Shallow events often produce stronger surface shaking nearby."><CircleHelp /><span className="sr-only">About depth</span></button></legend>
        <div className="segmented vertical-on-narrow">
          {(['all', 'shallow', 'intermediate', 'deep'] as const).map((depth) => (
            <button type="button" key={depth} aria-pressed={filters.depth === depth} className={filters.depth === depth ? 'is-active' : ''} onClick={() => onChange(updateFilter(filters, 'depth', depth))}>
              {depth === 'all' ? 'Any' : depth === 'shallow' ? '<70 km' : depth === 'intermediate' ? '70–300' : '300+ km'}
            </button>
          ))}
        </div>
      </fieldset>

      <div className="two-fields">
        <label className="field"><span>USGS alert</span><select value={filters.alert} onChange={(event) => onChange(updateFilter(filters, 'alert', event.target.value as FilterState['alert']))}><option value="all">Any alert</option><option value="none">No alert</option><option value="green">Green</option><option value="yellow">Yellow</option><option value="orange">Orange</option><option value="red">Red</option></select></label>
        <label className="field"><span>Tsunami flag</span><select value={filters.tsunami} onChange={(event) => onChange(updateFilter(filters, 'tsunami', event.target.value as FilterState['tsunami']))}><option value="all">Either</option><option value="yes">Flagged</option><option value="no">Not flagged</option></select></label>
      </div>

      <div className="two-fields">
        <label className="field"><span>Review status</span><select value={filters.status} onChange={(event) => onChange(updateFilter(filters, 'status', event.target.value as FilterState['status']))}><option value="all">Any status</option><option value="reviewed">Reviewed</option><option value="automatic">Automatic</option></select></label>
        <label className="field"><span>Geographic area</span><select value={filters.area} onChange={(event) => onChange(updateFilter(filters, 'area', event.target.value as FilterState['area']))}><option value="world">Whole world</option><option value="viewport">Visible map</option></select></label>
      </div>

      <div className="filter-panel-footer">
        <p><strong>{resultCount.toLocaleString()}</strong> of {totalCount.toLocaleString()} events</p>
        <button type="button" className="text-button" onClick={() => onChange({ ...DEFAULT_FILTERS, range: filters.range })}><RotateCcw /> Reset filters</button>
      </div>
    </div>
  )
}

function EventRow({ event, selected, highlighted, onSelect, onHover }: { event: EarthquakeFeature; selected: boolean; highlighted: boolean; onSelect: () => void; onHover: (id: string | null) => void }) {
  const depth = event.geometry.coordinates[2]
  return (
    <li>
      <button
        type="button"
        className={`event-row ${selected ? 'is-selected' : ''} ${!highlighted ? 'is-muted' : ''}`}
        onClick={onSelect}
        onMouseEnter={() => onHover(event.id)}
        onMouseLeave={() => onHover(null)}
        onFocus={() => onHover(event.id)}
        onBlur={() => onHover(null)}
        aria-current={selected ? 'true' : undefined}
      >
        <span className={`event-mag depth-${depthBand(depth).toLowerCase()}`}><b>{formatMagnitude(event.properties.mag)}</b><small>MAG</small></span>
        <span className="event-copy">
          <strong>{event.properties.place ?? 'Location pending review'}</strong>
          <span><Clock3 /> {formatRelativeTime(event.properties.time)} <i /> {formatDepth(depth)}</span>
          <span className="event-tags">
            {event.properties.alert && <em className={`status-tag alert-${event.properties.alert}`}>{event.properties.alert} alert</em>}
            {event.properties.tsunami === 1 && <em className="status-tag tsunami"><Waves /> tsunami flag</em>}
            {event.properties.status === 'reviewed' && <em className="status-tag reviewed"><ShieldCheck /> reviewed</em>}
          </span>
        </span>
        <span className="event-sig"><small>SIG</small><b>{event.properties.sig}</b></span>
      </button>
    </li>
  )
}

function EventDetail({ event, allEvents, onClose }: { event: EarthquakeFeature; allEvents: EarthquakeFeature[]; onClose: () => void }) {
  const [longitude, latitude, depth] = event.geometry.coordinates
  const descriptionId = `event-detail-${event.id}`
  const closeRef = useRef<HTMLButtonElement>(null)

  useEffect(() => {
    closeRef.current?.focus()
    const onKey = (keyEvent: KeyboardEvent) => {
      if (keyEvent.key === 'Escape') onClose()
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [onClose])

  return (
    <aside className="event-detail" aria-labelledby={descriptionId}>
      <div className="detail-topline">
        <span>Event record · {event.id}</span>
        <button ref={closeRef} className="icon-button" type="button" onClick={onClose} aria-label="Close event details"><X /></button>
      </div>
      <div className="detail-hero">
        <div className={`detail-magnitude depth-${depthBand(depth).toLowerCase()}`}><small>Magnitude</small><strong>{formatMagnitude(event.properties.mag)}</strong><span>{event.properties.magType?.toUpperCase() ?? 'Type pending'}</span></div>
        <div><p className="eyebrow">{magnitudeLabel(event.properties.mag)}</p><h2 id={descriptionId}>{event.properties.place ?? 'Location pending review'}</h2><p className="detail-context">{percentileContext(event, allEvents)}</p></div>
      </div>

      <div className={`assessment ${event.properties.alert ? `alert-${event.properties.alert}` : ''}`}>
        <AlertTriangle aria-hidden="true" />
        <div><strong>{statusCopy(event)}</strong><p>Magnitude alone does not determine damage. Depth, distance, construction, and local ground conditions also matter.</p></div>
      </div>

      <dl className="detail-grid">
        <div><dt>Local time</dt><dd>{formatDateTime(event.properties.time)}</dd></div>
        <div><dt>Universal time</dt><dd>{formatUtc(event.properties.time)}</dd></div>
        <div><dt>Depth</dt><dd>{formatDepth(depth)} <small>{depthBand(depth)}</small></dd></div>
        <div><dt>Significance</dt><dd>{event.properties.sig} <small>USGS combined measure</small></dd></div>
        <div><dt>Felt reports</dt><dd>{event.properties.felt == null ? 'Not reported' : event.properties.felt.toLocaleString()}</dd></div>
        <div><dt>Review</dt><dd>{event.properties.status === 'reviewed' ? 'Reviewed by an analyst' : 'Automatic solution'}</dd></div>
        <div><dt>Impact alert</dt><dd>{event.properties.alert ? `${event.properties.alert[0].toUpperCase()}${event.properties.alert.slice(1)} PAGER alert` : 'No PAGER alert issued'}</dd></div>
        <div><dt>Tsunami</dt><dd>{event.properties.tsunami === 1 ? 'USGS feed flag present' : 'No flag in USGS feed'}</dd></div>
        <div className="coordinates"><dt>Coordinates</dt><dd>{latitude.toFixed(4)}°, {longitude.toFixed(4)}°</dd></div>
        <div><dt>Last revised</dt><dd>{formatRelativeTime(event.properties.updated)}</dd></div>
      </dl>

      <div className="detail-notes">
        <details><summary>What does “significance” mean?</summary><p>USGS significance combines magnitude with factors such as felt reports, estimated intensity, and alert level. It is useful for ranking attention, not predicting harm.</p></details>
        <details><summary>Data status and safety</summary><p>Earthquake solutions can change as more observations arrive. This observatory is not an emergency alert service. Follow official local authorities for safety information.</p></details>
      </div>

      <a className="primary-link" href={event.properties.url} target="_blank" rel="noreferrer">Open official USGS event page <ArrowUpRight /></a>
    </aside>
  )
}

function ActiveFilters({ filters, onChange }: { filters: FilterState; onChange: (filters: FilterState) => void }) {
  const chips: { key: keyof FilterState; label: string; reset: FilterState[keyof FilterState] }[] = []
  if (filters.minMagnitude !== DEFAULT_FILTERS.minMagnitude) chips.push({ key: 'minMagnitude', label: `M ${filters.minMagnitude.toFixed(1)}+`, reset: DEFAULT_FILTERS.minMagnitude })
  if (filters.depth !== 'all') chips.push({ key: 'depth', label: `${filters.depth} depth`, reset: 'all' })
  if (filters.alert !== 'all') chips.push({ key: 'alert', label: `${filters.alert} alert`, reset: 'all' })
  if (filters.tsunami !== 'all') chips.push({ key: 'tsunami', label: filters.tsunami === 'yes' ? 'Tsunami flagged' : 'No tsunami flag', reset: 'all' })
  if (filters.status !== 'all') chips.push({ key: 'status', label: filters.status, reset: 'all' })
  if (filters.query) chips.push({ key: 'query', label: `“${filters.query}”`, reset: '' })
  if (filters.area !== 'world') chips.push({ key: 'area', label: 'Visible map only', reset: 'world' })
  if (!chips.length) return null
  return <div className="active-filters" aria-label="Active filters">{chips.map((chip) => <button key={chip.key} type="button" onClick={() => onChange({ ...filters, [chip.key]: chip.reset })}>{chip.label}<X /></button>)}<button className="clear-all" type="button" onClick={() => onChange({ ...DEFAULT_FILTERS, range: filters.range })}>Clear all</button></div>
}

export default function App() {
  const [filters, setFilters] = useState<FilterState>(initialState.filters)
  const [feed, setFeed] = useState<EarthquakeFeed | null>(null)
  const [selectedId, setSelectedId] = useState<string | null>(initialState.selectedId)
  const [hoveredId, setHoveredId] = useState<string | null>(null)
  const [highlightedIds, setHighlightedIds] = useState<Set<string> | null>(null)
  const [bounds, setBounds] = useState<MapBounds | null>(null)
  const [loading, setLoading] = useState(true)
  const [refreshing, setRefreshing] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [offline, setOffline] = useState(!navigator.onLine)
  const [filtersOpen, setFiltersOpen] = useState(false)
  const [mobileView, setMobileView] = useState<'map' | 'list'>('map')
  const [visibleRows, setVisibleRows] = useState(120)
  const [fitSignal, setFitSignal] = useState(0)
  const [copied, setCopied] = useState(false)
  const [clock, setClock] = useState(Date.now())
  const abortRef = useRef<AbortController | null>(null)

  const fetchData = useCallback(async (range: TimeRange, background = false) => {
    abortRef.current?.abort()
    const controller = new AbortController()
    abortRef.current = controller
    background ? setRefreshing(true) : setLoading(true)
    setError(null)
    try {
      const response = await fetch(FEEDS[range], { signal: controller.signal, cache: 'no-store' })
      if (!response.ok) throw new Error(`USGS returned ${response.status}`)
      const nextFeed = await response.json() as EarthquakeFeed
      if (!Array.isArray(nextFeed.features)) throw new Error('Unexpected USGS response')
      setFeed(nextFeed)
      cacheFeed(range, nextFeed)
    } catch (fetchError) {
      if (fetchError instanceof DOMException && fetchError.name === 'AbortError') return
      const cached = loadCachedFeed(range)
      if (cached) setFeed(cached)
      setError(cached ? 'Live refresh failed. Showing the most recent saved USGS data.' : 'Live USGS data could not be loaded. Check your connection and try again.')
    } finally {
      if (!controller.signal.aborted) {
        setLoading(false)
        setRefreshing(false)
      }
    }
  }, [])

  useEffect(() => {
    fetchData(filters.range)
    setVisibleRows(120)
    return () => abortRef.current?.abort()
  }, [filters.range, fetchData])

  useEffect(() => {
    const interval = window.setInterval(() => setClock(Date.now()), 30_000)
    const online = () => { setOffline(false); fetchData(filters.range, Boolean(feed)) }
    const offlineHandler = () => setOffline(true)
    window.addEventListener('online', online)
    window.addEventListener('offline', offlineHandler)
    return () => {
      window.clearInterval(interval)
      window.removeEventListener('online', online)
      window.removeEventListener('offline', offlineHandler)
    }
  }, [feed, filters.range, fetchData])

  useEffect(() => writeUrlState(filters, selectedId), [filters, selectedId])

  const filteredEvents = useMemo(() => filterEvents(feed?.features ?? [], filters, bounds), [feed, filters, bounds])
  const selectedEvent = useMemo(() => (feed?.features ?? []).find((event) => event.id === selectedId) ?? null, [feed, selectedId])
  const strongest = useMemo(() => [...filteredEvents].sort((a, b) => (b.properties.mag ?? -10) - (a.properties.mag ?? -10))[0] ?? null, [filteredEvents])
  const recentCount = filteredEvents.filter((event) => clock - event.properties.time <= 24 * 60 * 60 * 1000).length
  const oldestHalf = filteredEvents.filter((event) => event.properties.time < clock - ({ hour: 30, day: 12 * 60, week: 3.5 * 24 * 60, month: 15 * 24 * 60 }[filters.range]) * 60_000).length
  const newerHalf = filteredEvents.length - oldestHalf
  const trend = oldestHalf === 0 ? null : Math.round(((newerHalf - oldestHalf) / oldestHalf) * 100)
  const activeFilterCount = [filters.minMagnitude !== DEFAULT_FILTERS.minMagnitude, filters.depth !== 'all', filters.alert !== 'all', filters.tsunami !== 'all', filters.status !== 'all', Boolean(filters.query), filters.area !== 'world'].filter(Boolean).length
  const staleMinutes = feed ? Math.max(0, Math.floor((clock - feed.metadata.generated) / 60_000)) : 0
  const isStale = staleMinutes > 30

  const selectEvent = useCallback((event: EarthquakeFeature) => {
    setSelectedId(event.id)
    setMobileView('map')
  }, [])
  const updateBounds = useCallback((nextBounds: MapBounds) => setBounds(nextBounds), [])
  const updateHighlight = useCallback((ids: Set<string> | null) => setHighlightedIds(ids), [])

  const share = async () => {
    const shareData = { title: selectedEvent?.properties.title ?? 'Seismic Field', text: selectedEvent ? `${selectedEvent.properties.title} on Seismic Field` : `Explore ${filteredEvents.length} recent earthquakes on Seismic Field`, url: window.location.href }
    try {
      if (navigator.share) await navigator.share(shareData)
      else {
        await navigator.clipboard.writeText(window.location.href)
        setCopied(true)
        window.setTimeout(() => setCopied(false), 2000)
      }
    } catch {
      // Sharing can be dismissed without changing the exploration state.
    }
  }

  return (
    <div className="app-shell">
      <header className="site-header">
        <a className="brand" href="/" aria-label="Seismic Field home"><span className="brand-mark"><i /><i /><i /></span><span><strong>Seismic Field</strong><small>Live earthquake observatory</small></span></a>
        <TimeTabs value={filters.range} onChange={(range) => setFilters(updateFilter(filters, 'range', range))} />
        <div className="header-actions">
          <button className="header-button" type="button" onClick={() => fetchData(filters.range, Boolean(feed))} disabled={refreshing}><RefreshCw className={refreshing ? 'is-spinning' : ''} /><span>{refreshing ? 'Refreshing' : 'Refresh'}</span></button>
          <button className="header-button" type="button" onClick={share}><Share2 /><span>{copied ? 'Link copied' : 'Share'}</span></button>
        </div>
      </header>

      <div className="data-status" role="status" aria-live="polite">
        <span className={error || offline || isStale ? 'status-dot is-warning' : 'status-dot'} />
        {loading && !feed ? 'Connecting to the USGS live feed…' : error ?? (offline ? `Offline · showing data generated ${formatRelativeTime(feed?.metadata.generated ?? clock, clock)}` : `USGS feed generated ${formatRelativeTime(feed?.metadata.generated ?? clock, clock)}${isStale ? ' · data may be stale' : ''}`)}
        <span>Earthquake records may be revised.</span>
        {(error || offline || isStale) && <button type="button" onClick={() => fetchData(filters.range, Boolean(feed))}>Try live refresh</button>}
      </div>

      <main>
        <section className="observation-header" aria-labelledby="page-title">
          <div className="observation-copy">
            <p className="eyebrow">Global field · {RANGE_LABELS[filters.range]}</p>
            <h1 id="page-title">The ground in motion, <em>right now.</em></h1>
            <p>Explore verified and automatic earthquake records as they arrive. Select any signal to connect its place, time, depth, and significance.</p>
          </div>
          <div className="field-summary" aria-label="Current activity summary">
            <div><small>In view</small><strong>{filteredEvents.length.toLocaleString()}</strong><span>of {(feed?.features.length ?? 0).toLocaleString()} loaded</span></div>
            <div><small>Past 24 hours</small><strong>{recentCount.toLocaleString()}</strong><span>matching events</span></div>
            <div className="strongest-summary"><small>Strongest in view</small>{strongest ? <button type="button" onClick={() => selectEvent(strongest)}><strong>M{formatMagnitude(strongest.properties.mag)}</strong><span>{strongest.properties.place ?? 'Location pending'}</span></button> : <strong>—</strong>}</div>
            <div><small>Activity balance</small><strong>{trend == null ? '—' : `${trend > 0 ? '+' : ''}${trend}%`}</strong><span>newer vs earlier half</span></div>
          </div>
        </section>

        <Timeline events={filteredEvents} range={filters.range} selectedEvent={selectedEvent} onHighlight={updateHighlight} />

        <div className="mobile-view-switch" aria-label="Choose primary view">
          <button type="button" className={mobileView === 'map' ? 'is-active' : ''} onClick={() => setMobileView('map')}><MapIcon /> Map</button>
          <button type="button" className={mobileView === 'list' ? 'is-active' : ''} onClick={() => setMobileView('list')}><List /> Events <span>{filteredEvents.length}</span></button>
        </div>

        <section className="explorer" aria-label="Earthquake explorer">
          <aside className="filters-column">
            <FilterPanel filters={filters} onChange={setFilters} resultCount={filteredEvents.length} totalCount={feed?.features.length ?? 0} />
            <div className="source-note"><ShieldCheck /><p><strong>Public information, not an alert service.</strong> Data comes from the USGS and can change. For urgent guidance, follow local authorities.</p></div>
          </aside>

          <div className={`map-column ${mobileView === 'map' ? 'is-mobile-active' : ''}`}>
            <div className="map-toolbar">
              <button type="button" onClick={() => setFiltersOpen(true)}><Filter /> Filters {activeFilterCount > 0 && <span>{activeFilterCount}</span>}</button>
              <button type="button" onClick={() => setFitSignal((value) => value + 1)} disabled={filteredEvents.length === 0}><LocateFixed /> Fit results</button>
              <button type="button" className={filters.area === 'viewport' ? 'is-active' : ''} aria-pressed={filters.area === 'viewport'} onClick={() => setFilters(updateFilter(filters, 'area', filters.area === 'viewport' ? 'world' : 'viewport'))}><Crosshair /> Visible area</button>
            </div>
            {loading && !feed ? <div className="map-loading" aria-label="Loading map data"><div className="contour-loader"><i /><i /><i /></div><strong>Reading the seismic field</strong><span>Connecting to live USGS observations…</span></div> : filteredEvents.length === 0 ? <div className="empty-map"><Layers3 /><h2>No signals match this field</h2><p>These constraints exclude all loaded events. Clear filters or expand the map area to recover the view.</p><button type="button" onClick={() => setFilters({ ...DEFAULT_FILTERS, range: filters.range })}>Reset filters</button></div> : <MapView events={filteredEvents} selectedId={selectedId} highlightedIds={highlightedIds} onSelect={selectEvent} onHover={setHoveredId} hoveredId={hoveredId} onBoundsChange={updateBounds} fitSignal={fitSignal} />}
          </div>

          <section id="event-stream" className={`stream-column ${mobileView === 'list' ? 'is-mobile-active' : ''}`} aria-labelledby="stream-title">
            <div className="stream-heading">
              <div><p className="eyebrow">Synchronized event stream</p><h2 id="stream-title">{filteredEvents.length.toLocaleString()} signals</h2></div>
              <label>Sort <select value={filters.sort} onChange={(event) => setFilters(updateFilter(filters, 'sort', event.target.value as FilterState['sort']))}><option value="significance">Significance</option><option value="magnitude">Magnitude</option><option value="newest">Newest</option><option value="depth">Deepest</option></select></label>
            </div>
            <ActiveFilters filters={filters} onChange={setFilters} />
            {loading && !feed ? <ul className="event-skeleton" aria-label="Loading events">{Array.from({ length: 8 }, (_, index) => <li key={index}><i /><span /><span /></li>)}</ul> : error && !feed ? <div className="stream-empty"><AlertTriangle /><h3>USGS data is unavailable</h3><p>No fictional or sample events are being shown. Retry when your connection is available.</p><button type="button" onClick={() => fetchData(filters.range)}>Retry</button></div> : filteredEvents.length === 0 ? <div className="stream-empty"><Search /><h3>No matching events</h3><p>Try a lower magnitude, a wider depth range, or the whole-world area.</p><button type="button" onClick={() => setFilters({ ...DEFAULT_FILTERS, range: filters.range })}>Reset filters</button></div> : <><ol className="event-list">{filteredEvents.slice(0, visibleRows).map((event) => <EventRow key={event.id} event={event} selected={event.id === selectedId} highlighted={!highlightedIds || highlightedIds.has(event.id)} onSelect={() => selectEvent(event)} onHover={setHoveredId} />)}</ol>{visibleRows < filteredEvents.length && <button className="load-more" type="button" onClick={() => setVisibleRows((count) => count + 150)}>Show 150 more <ChevronDown /></button>}</>}
          </section>

          {selectedEvent && <EventDetail event={selectedEvent} allEvents={filteredEvents.length ? filteredEvents : feed?.features ?? []} onClose={() => setSelectedId(null)} />}
        </section>
      </main>

      {filtersOpen && <div className="sheet-backdrop" onMouseDown={(event) => { if (event.currentTarget === event.target) setFiltersOpen(false) }}><div className="filter-sheet" role="dialog" aria-modal="true" aria-label="Earthquake filters"><FilterPanel filters={filters} onChange={setFilters} resultCount={filteredEvents.length} totalCount={feed?.features.length ?? 0} onClose={() => setFiltersOpen(false)} /><button className="apply-filters" type="button" onClick={() => setFiltersOpen(false)}>View {filteredEvents.length.toLocaleString()} events</button></div></div>}

      <footer><p>Data: <a href="https://earthquake.usgs.gov/earthquakes/feed/" target="_blank" rel="noreferrer">U.S. Geological Survey <ArrowUpRight /></a> · Basemap: OpenStreetMap contributors</p><p>Seismic Field does not predict earthquakes or guarantee safety.</p></footer>
      <div className="sr-only" aria-live="polite">{selectedEvent ? `Selected ${selectedEvent.properties.title}` : ''}</div>
    </div>
  )
}

input.content:
@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700&family=Newsreader:opsz,wght@6..72,500;6..72,600&display=swap');

:root {
  color-scheme: light;
  font-family: 'Manrope', ui-sans-serif, system-ui, sans-serif;
  color: #172521;
  background: #edf0ea;
  font-synthesis: none;
  --ink: #172521;
  --ink-soft: #4e5b56;
  --muted: #718078;
  --paper: #f7f7f2;
  --paper-raised: #fffefa;
  --field: #dfe5dc;
  --line: #cbd2c9;
  --line-strong: #aeb8ae;
  --pine: #123c35;
  --pine-deep: #0d2d28;
  --mineral: #2e7468;
  --copper: #bd694a;
  --amber: #d59a38;
  --alert-red: #ad3d3d;
  --depth-shallow: #c96f4c;
  --depth-mid: #3d8074;
  --depth-deep: #445b78;
  --shadow: 0 20px 55px rgba(24, 43, 36, .14);
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body { margin: 0; min-width: 320px; min-height: 100vh; background: var(--paper); }
button, input, select { font: inherit; }
button, select, input { accent-color: var(--mineral); }
button { color: inherit; }
a { color: inherit; }
svg { width: 18px; height: 18px; stroke-width: 1.8; }
::selection { color: white; background: var(--mineral); }
:focus-visible { outline: 3px solid #e4a54c; outline-offset: 3px; }
.sr-only { position: absolute!important; width: 1px!important; height: 1px!important; padding: 0!important; margin: -1px!important; overflow: hidden!important; clip: rect(0,0,0,0)!important; white-space: nowrap!important; border: 0!important; }
.skip-link { position: fixed; left: 16px; top: 12px; z-index: 10000; transform: translateY(-150%); padding: 12px 16px; color: white; background: var(--pine); border-radius: 8px; }
.skip-link:focus { transform: none; }

.app-shell { min-height: 100vh; overflow-x: hidden; background: radial-gradient(circle at 50% -20%, #fff 0, transparent 34%), var(--paper); }
.site-header { position: sticky; top: 0; z-index: 1000; height: 72px; display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; gap: 24px; padding: 0 28px; color: white; background: rgba(13, 45, 40, .97); border-bottom: 1px solid rgba(255,255,255,.12); backdrop-filter: blur(16px); }
.brand { display: inline-flex; align-items: center; gap: 12px; width: max-content; text-decoration: none; }
.brand > span:last-child { display: flex; flex-direction: column; line-height: 1.05; }
.brand strong { font-family: 'Newsreader', Georgia, serif; font-size: 21px; font-weight: 600; letter-spacing: .01em; }
.brand small { margin-top: 4px; color: #b9cac4; font-family: 'DM Mono', monospace; font-size: 9px; letter-spacing: .08em; text-transform: uppercase; }
.brand-mark { position: relative; display: grid; place-items: center; width: 38px; height: 38px; border: 1px solid rgba(255,255,255,.25); border-radius: 50%; }
.brand-mark i { position: absolute; width: 6px; height: 6px; border: 1px solid #dba46f; border-radius: 50%; }
.brand-mark i:nth-child(1) { width: 15px; height: 15px; opacity: .85; }
.brand-mark i:nth-child(2) { width: 25px; height: 25px; opacity: .55; }
.brand-mark i:nth-child(3) { width: 34px; height: 34px; opacity: .3; }
.time-tabs { display: flex; align-items: center; padding: 4px; background: rgba(255,255,255,.08); border: 1px solid rgba(255,255,255,.12); border-radius: 10px; }
.time-tabs button { min-width: 56px; min-height: 40px; padding: 7px 12px; color: #bcd0c9; background: transparent; border: 0; border-radius: 7px; cursor: pointer; font-family: 'DM Mono', monospace; font-size: 12px; font-weight: 500; }
.time-tabs button span { position: absolute; clip: rect(0 0 0 0); }
.time-tabs button:hover { color: white; background: rgba(255,255,255,.08); }
.time-tabs button.is-active { color: var(--pine-deep); background: #f3efe5; box-shadow: 0 2px 8px rgba(0,0,0,.15); }
.header-actions { justify-self: end; display: flex; gap: 6px; }
.header-button { display: inline-flex; align-items: center; gap: 8px; min-height: 44px; padding: 0 12px; color: #e8f0ed; background: transparent; border: 0; border-radius: 8px; cursor: pointer; }
.header-button:hover { background: rgba(255,255,255,.09); }
.header-button:disabled { opacity: .65; cursor: wait; }
.is-spinning { animation: spin .8s linear infinite; }
@keyframes spin { to { transform: rotate(1turn); } }
.data-status { min-height: 34px; display: flex; align-items: center; justify-content: center; gap: 8px; padding: 7px 24px; color: #4f5e58; background: #e9ece5; border-bottom: 1px solid var(--line); font-family: 'DM Mono', monospace; font-size: 10px; letter-spacing: .02em; }
.data-status > span:nth-of-type(2) { padding-left: 8px; color: #75827d; border-left: 1px solid var(--line-strong); }
.data-status button { padding: 2px 5px; color: var(--pine); background: transparent; border: 0; border-bottom: 1px solid currentColor; cursor: pointer; font-size: 10px; }
.status-dot { width: 7px; height: 7px; flex: 0 0 auto; background: #347e68; border-radius: 50%; box-shadow: 0 0 0 3px rgba(52,126,104,.13); }
.status-dot.is-warning { background: var(--amber); box-shadow: 0 0 0 3px rgba(213,154,56,.18); }

main { width: min(1920px, 100%); margin: 0 auto; }
.observation-header { display: grid; grid-template-columns: minmax(320px, .9fr) minmax(550px, 1.1fr); gap: clamp(32px, 6vw, 100px); align-items: end; padding: clamp(36px, 5vw, 72px) clamp(24px, 4vw, 64px) 38px; background-image: radial-gradient(ellipse at 15% 20%, rgba(47,116,104,.08), transparent 30%), repeating-radial-gradient(ellipse at 15% 30%, transparent 0 34px, rgba(18,60,53,.045) 35px, transparent 36px 48px); }
.eyebrow { margin: 0 0 10px; color: var(--mineral); font-family: 'DM Mono', monospace; font-size: 10px; font-weight: 500; letter-spacing: .13em; text-transform: uppercase; }
.observation-copy h1 { max-width: 720px; margin: 0; font-family: 'Newsreader', Georgia, serif; font-size: clamp(44px, 5.2vw, 82px); font-weight: 500; line-height: .92; letter-spacing: -.045em; }
.observation-copy h1 em { display: block; color: var(--mineral); font-weight: 500; }
.observation-copy > p:last-child { max-width: 650px; margin: 24px 0 0; color: var(--ink-soft); font-size: 15px; line-height: 1.7; }
.field-summary { display: grid; grid-template-columns: repeat(4, 1fr); border-top: 1px solid var(--line-strong); border-bottom: 1px solid var(--line-strong); }
.field-summary > div { min-width: 0; min-height: 126px; padding: 21px 18px; border-left: 1px solid var(--line); }
.field-summary > div:first-child { border-left: 0; }
.field-summary small { display: block; margin-bottom: 16px; color: var(--muted); font-family: 'DM Mono', monospace; font-size: 9px; letter-spacing: .08em; text-transform: uppercase; }
.field-summary strong { display: block; font-family: 'Newsreader', Georgia, serif; font-size: clamp(28px, 2.7vw, 44px); font-weight: 500; line-height: .9; }
.field-summary span { display: block; margin-top: 10px; color: var(--ink-soft); font-size: 10px; line-height: 1.4; }
.strongest-summary button { width: 100%; padding: 0; text-align: left; background: transparent; border: 0; cursor: pointer; }
.strongest-summary button:hover strong { color: var(--copper); }

.timeline { margin: 0 clamp(24px, 4vw, 64px) 26px; padding: 20px 24px 15px; background: #ecf0e9; border: 1px solid var(--line); border-radius: 12px; box-shadow: inset 0 1px rgba(255,255,255,.7); }
.timeline-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 24px; }
.timeline h2 { margin: 0; font-family: 'Newsreader', Georgia, serif; font-size: 22px; font-weight: 600; }
.timeline-readout { min-height: 40px; display: flex; align-items: center; gap: 8px; color: var(--muted); font-size: 11px; }
.timeline-readout strong { color: var(--pine); font-family: 'Newsreader', serif; font-size: 25px; }
.timeline-readout button { margin-left: 6px; padding: 5px 8px; color: var(--pine); background: white; border: 1px solid var(--line); border-radius: 5px; cursor: pointer; font-size: 10px; }
.seismic-ribbon { position: relative; height: 56px; display: grid; grid-template-columns: repeat(48, 1fr); align-items: end; gap: 2px; margin-top: 14px; border-bottom: 1px solid #9aa89f; }
.seismic-ribbon > span { min-width: 1px; background: #7da095; border-radius: 2px 2px 0 0; opacity: .65; transition: opacity .12s, background-color .12s, transform .12s; }
.seismic-ribbon > span.has-notable { background: var(--copper); opacity: .9; }
.seismic-ribbon > span.is-active { background: var(--pine); opacity: 1; transform: scaleX(1.45); transform-origin: bottom; }
.timeline-needle { position: absolute; top: -5px; bottom: -6px; width: 1px; background: var(--pine); pointer-events: none; }
.timeline-needle::before { content: ''; position: absolute; top: -2px; left: -4px; width: 9px; height: 9px; background: var(--paper-raised); border: 2px solid var(--pine); border-radius: 50%; }
.timeline-slider-label { display: grid; grid-template-columns: 45px 1fr 35px; align-items: center; gap: 8px; margin-top: -9px; color: var(--muted); font-family: 'DM Mono', monospace; font-size: 9px; text-transform: uppercase; }
.timeline-slider-label input { position: relative; z-index: 2; width: 100%; height: 44px; margin: 0; opacity: .01; cursor: ew-resize; }
.timeline-axis { display: flex; justify-content: space-between; margin: -8px 42px 0 50px; color: var(--muted); font-family: 'DM Mono', monospace; font-size: 8px; }
.timeline-table { margin-top: 10px; color: var(--ink-soft); font-size: 11px; }
.timeline-table summary { width: max-content; cursor: pointer; color: var(--pine); }
.timeline-table ol { max-height: 160px; overflow: auto; line-height: 1.7; }

.mobile-view-switch { display: none; }
.explorer { position: relative; display: grid; grid-template-columns: 274px minmax(480px, 1fr) 370px; min-height: 720px; margin: 0 clamp(12px, 2vw, 30px) 32px; overflow: hidden; background: var(--paper-raised); border: 1px solid var(--line-strong); border-radius: 14px; box-shadow: var(--shadow); }
.filters-column { min-width: 0; padding: 22px 20px; overflow-y: auto; background: #eef1ea; border-right: 1px solid var(--line); }
.filter-panel-heading { display: flex; align-items: center; justify-content: space-between; margin-bottom: 22px; }
.filter-panel h2 { margin: 0; font-family: 'Newsreader', Georgia, serif; font-size: 28px; }
.icon-button { width: 44px; height: 44px; display: grid; place-items: center; padding: 0; background: transparent; border: 1px solid var(--line); border-radius: 50%; cursor: pointer; }
.icon-button:hover { background: var(--field); }
.field { display: block; margin: 0 0 22px; padding: 0; border: 0; }
.field > span, .field legend { display: flex; align-items: center; gap: 5px; margin-bottom: 8px; color: var(--ink); font-size: 11px; font-weight: 700; }
.field small { display: block; margin-top: 7px; color: var(--muted); font-size: 9px; line-height: 1.45; }
.search-field > div { display: flex; align-items: center; height: 44px; padding: 0 10px; background: var(--paper-raised); border: 1px solid var(--line-strong); border-radius: 7px; }
.search-field svg { flex: 0 0 auto; color: var(--muted); }
.search-field input { min-width: 0; width: 100%; height: 100%; padding: 0 8px; background: transparent; border: 0; outline: 0; font-size: 12px; }
.term-help { display: inline-grid; place-items: center; padding: 2px; color: var(--muted); background: transparent; border: 0; cursor: help; }
.term-help svg { width: 14px; height: 14px; }
.magnitude-filter { position: relative; }
.magnitude-value { position: absolute; right: 0; top: -5px; color: var(--pine); font-family: 'DM Mono', monospace; font-size: 13px; font-weight: 500; }
.magnitude-filter input { width: 100%; }
.range-labels { display: flex; justify-content: space-between; margin-top: 2px; color: var(--muted); font-family: 'DM Mono', monospace; font-size: 8px; }
.segmented { display: grid; grid-template-columns: repeat(4, 1fr); padding: 3px; background: #dce2da; border-radius: 7px; }
.segmented button { min-height: 36px; padding: 4px; background: transparent; border: 0; border-radius: 5px; cursor: pointer; font-size: 8px; }
.segmented button.is-active { color: white; background: var(--pine); }
.two-fields { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.field select, .stream-heading select { width: 100%; min-height: 42px; padding: 0 28px 0 9px; color: var(--ink); background: var(--paper-raised); border: 1px solid var(--line-strong); border-radius: 7px; font-size: 10px; }
.filter-panel-footer { padding-top: 14px; border-top: 1px solid var(--line); }
.filter-panel-footer p { margin: 0 0 10px; color: var(--muted); font-size: 10px; }
.filter-panel-footer p strong { color: var(--ink); font-size: 15px; }
.text-button { display: inline-flex; align-items: center; gap: 6px; min-height: 36px; padding: 0; color: var(--pine); background: transparent; border: 0; cursor: pointer; font-size: 10px; font-weight: 700; }
.text-button svg { width: 14px; }
.source-note { display: flex; gap: 10px; margin-top: 24px; padding: 14px; color: #54625c; background: rgba(255,255,255,.55); border: 1px solid var(--line); border-radius: 8px; }
.source-note svg { flex: 0 0 auto; color: var(--mineral); }
.source-note p { margin: 0; font-size: 9px; line-height: 1.6; }
.source-note strong { color: var(--ink); }

.map-column { position: relative; min-width: 0; min-height: 720px; background: #dbe2dc; }
.map-shell, .map-canvas { width: 100%; height: 100%; min-height: 720px; }
.map-canvas { z-index: 1; background: #d8dfda; }
.map-toolbar { position: absolute; z-index: 500; top: 14px; left: 14px; display: flex; gap: 7px; }
.map-toolbar button { min-height: 42px; display: inline-flex; align-items: center; gap: 7px; padding: 0 11px; background: rgba(255,254,250,.95); border: 1px solid #acb7ae; border-radius: 7px; box-shadow: 0 5px 14px rgba(20,40,34,.12); cursor: pointer; font-size: 10px; font-weight: 700; }
.map-toolbar button:hover, .map-toolbar button.is-active { color: white; background: var(--pine); border-color: var(--pine); }
.map-toolbar button:disabled { opacity: .45; cursor: not-allowed; }
.map-toolbar button > span { min-width: 18px; padding: 2px 4px; color: white; background: var(--copper); border-radius: 10px; font-family: 'DM Mono', monospace; font-size: 8px; text-align: center; }
.map-key { position: absolute; z-index: 500; left: 14px; bottom: 14px; display: flex; flex-wrap: wrap; gap: 10px; align-items: center; max-width: calc(100% - 92px); padding: 8px 10px; color: var(--ink-soft); background: rgba(255,254,250,.93); border: 1px solid #b6c0b8; border-radius: 6px; font-size: 8px; box-shadow: 0 4px 12px rgba(20,40,34,.1); }
.map-key span { display: flex; align-items: center; gap: 4px; }
.map-key i { width: 9px; height: 9px; border: 2px solid; border-radius: 50%; }
.map-key .key-shallow { border-color: var(--depth-shallow); }
.map-key .key-intermediate { border-color: var(--depth-mid); }
.map-key .key-deep { border-color: var(--depth-deep); }
.map-key .key-note { padding-left: 8px; border-left: 1px solid var(--line); }
.leaflet-container { font-family: 'Manrope', sans-serif; }
.leaflet-tile { filter: saturate(.58) sepia(.06) brightness(1.04) contrast(.92); }
.leaflet-control-attribution { color: #65716d!important; background: rgba(250,250,245,.78)!important; font-size: 8px!important; }
.leaflet-tooltip { max-width: 260px; padding: 8px 10px; color: var(--ink); background: var(--paper-raised); border: 1px solid var(--line-strong); border-radius: 5px; box-shadow: 0 7px 20px rgba(20,40,34,.18); font-size: 10px; line-height: 1.45; }
.leaflet-tooltip strong { display: inline-block; margin-bottom: 2px; }
.quake-marker { display: grid!important; place-items: center; color: var(--ink); background: rgba(255,254,250,.92); border: 3px solid var(--depth-shallow); border-radius: 50%; box-shadow: 0 0 0 2px rgba(255,254,250,.8), 0 5px 12px rgba(24,42,36,.22); font-family: 'DM Mono', monospace; font-size: 10px; font-weight: 500; transition: opacity .15s, transform .15s, box-shadow .15s; }
.quake-marker.depth-intermediate { border-color: var(--depth-mid); }
.quake-marker.depth-deep { border-color: var(--depth-deep); border-style: double; border-width: 4px; }
.quake-marker.magnitude-notable { background: #fff8e8; border-width: 4px; }
.quake-marker.magnitude-major { color: white; background: var(--copper); border-color: #7d3528; border-width: 4px; }
.quake-marker.is-hovered { z-index: 900!important; transform: scale(1.15); box-shadow: 0 0 0 4px rgba(255,254,250,.9), 0 8px 20px rgba(24,42,36,.28); }
.quake-marker.is-selected { z-index: 950!important; transform: scale(1.18); box-shadow: 0 0 0 3px var(--pine), 0 0 0 7px rgba(255,254,250,.95), 0 10px 25px rgba(24,42,36,.3); }
.quake-marker.is-muted { opacity: .18; }
.quake-marker.has-tsunami::after { content: '≈'; position: absolute; right: -5px; top: -7px; width: 17px; height: 17px; display: grid; place-items: center; color: white; background: #356883; border: 2px solid white; border-radius: 50%; font-size: 11px; }
.quake-marker.alert-red::before, .quake-marker.alert-orange::before, .quake-marker.alert-yellow::before { content: '!'; position: absolute; left: -5px; top: -7px; width: 17px; height: 17px; display: grid; place-items: center; color: white; background: var(--alert-red); border: 2px solid white; border-radius: 50%; font-size: 10px; }
.quake-cluster { display: flex!important; flex-direction: column; align-items: center; justify-content: center; color: white; background: rgba(18,60,53,.9); border: 5px solid rgba(255,254,250,.78); border-radius: 50%; box-shadow: 0 5px 14px rgba(20,40,34,.25); }
.quake-cluster.cluster-notable { background: rgba(167,75,48,.93); }
.cluster-count { font-family: 'Newsreader', serif; font-size: 20px; line-height: .8; }
.cluster-mag { margin-top: 5px; font-family: 'DM Mono', monospace; font-size: 6px; text-transform: uppercase; }
.map-loading, .empty-map { position: absolute; inset: 0; z-index: 10; display: flex; flex-direction: column; align-items: center; justify-content: center; padding: 30px; text-align: center; background: #dde4de; }
.map-loading strong, .empty-map h2 { margin: 18px 0 6px; font-family: 'Newsreader', serif; font-size: 26px; }
.map-loading span, .empty-map p { max-width: 380px; margin: 0; color: var(--ink-soft); font-size: 12px; line-height: 1.6; }
.empty-map > svg { width: 38px; height: 38px; color: var(--mineral); }
.empty-map button, .stream-empty button { min-height: 42px; margin-top: 18px; padding: 0 15px; color: white; background: var(--pine); border: 0; border-radius: 6px; cursor: pointer; }
.contour-loader { position: relative; width: 74px; height: 74px; }
.contour-loader i { position: absolute; inset: 28px; border: 2px solid var(--mineral); border-radius: 48% 52% 56% 44%; animation: pulse 1.8s ease-in-out infinite; }
.contour-loader i:nth-child(2) { inset: 17px; opacity: .6; animation-delay: .2s; }
.contour-loader i:nth-child(3) { inset: 5px; opacity: .25; animation-delay: .4s; }
@keyframes pulse { 50% { transform: scale(1.1) rotate(8deg); } }

.stream-column { min-width: 0; max-height: 720px; overflow-y: auto; background: var(--paper-raised); border-left: 1px solid var(--line); scrollbar-color: #aeb8ae transparent; scrollbar-width: thin; }
.stream-heading { position: sticky; top: 0; z-index: 10; display: flex; align-items: flex-end; justify-content: space-between; gap: 12px; padding: 20px 18px 14px; background: rgba(255,254,250,.96); border-bottom: 1px solid var(--line); backdrop-filter: blur(12px); }
.stream-heading h2 { margin: 0; font-family: 'Newsreader', Georgia, serif; font-size: 26px; }
.stream-heading label { color: var(--muted); font-family: 'DM Mono', monospace; font-size: 8px; text-transform: uppercase; }
.stream-heading select { display: block; width: 118px; min-height: 36px; margin-top: 4px; }
.active-filters { display: flex; gap: 6px; padding: 10px 14px; overflow-x: auto; border-bottom: 1px solid var(--line); }
.active-filters button { flex: 0 0 auto; min-height: 30px; display: flex; align-items: center; gap: 4px; padding: 0 8px; color: var(--pine); background: #e3ece7; border: 1px solid #bbcbc2; border-radius: 15px; cursor: pointer; font-size: 8px; }
.active-filters button svg { width: 11px; }
.active-filters .clear-all { color: var(--copper); background: transparent; border-color: transparent; }
.event-list { margin: 0; padding: 0; list-style: none; }
.event-row { width: 100%; min-height: 112px; display: grid; grid-template-columns: 55px minmax(0, 1fr) 38px; gap: 12px; align-items: center; padding: 14px 16px; text-align: left; background: transparent; border: 0; border-bottom: 1px solid #dde1dc; cursor: pointer; transition: background .12s, opacity .12s; }
.event-row:hover { background: #f0f3ed; }
.event-row.is-selected { background: #e4ece7; box-shadow: inset 4px 0 var(--pine); }
.event-row.is-muted { opacity: .3; }
.event-mag { width: 52px; height: 52px; display: flex; flex-direction: column; align-items: center; justify-content: center; background: #faf7ef; border: 2px solid var(--depth-shallow); border-radius: 50%; }
.event-mag.depth-intermediate { border-color: var(--depth-mid); }
.event-mag.depth-deep { border-color: var(--depth-deep); border-style: double; border-width: 4px; }
.event-mag b { font-family: 'Newsreader', serif; font-size: 22px; font-weight: 600; line-height: 1; }
.event-mag small { margin-top: 3px; color: var(--muted); font-family: 'DM Mono', monospace; font-size: 7px; }
.event-copy { min-width: 0; display: block; }
.event-copy > strong { display: -webkit-box; overflow: hidden; color: var(--ink); font-size: 11px; line-height: 1.4; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.event-copy > span:not(.event-tags) { display: flex; align-items: center; gap: 4px; margin-top: 7px; color: var(--muted); font-family: 'DM Mono', monospace; font-size: 8px; }
.event-copy > span svg { width: 11px; height: 11px; }
.event-copy > span i { width: 2px; height: 2px; margin: 0 2px; background: var(--line-strong); border-radius: 50%; }
.event-tags { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 7px; }
.status-tag { display: inline-flex; align-items: center; gap: 3px; padding: 3px 5px; color: #486057; background: #e6ece8; border-radius: 3px; font-family: 'DM Mono', monospace; font-size: 6px; font-style: normal; font-weight: 500; text-transform: uppercase; }
.status-tag svg { width: 9px!important; height: 9px!important; }
.status-tag.alert-yellow { color: #68480d; background: #f8e4aa; }
.status-tag.alert-orange, .status-tag.alert-red { color: white; background: #a94d38; }
.status-tag.tsunami { color: #31576c; background: #dbe9ef; }
.event-sig { text-align: right; }
.event-sig small { display: block; color: var(--muted); font-family: 'DM Mono', monospace; font-size: 7px; }
.event-sig b { font-family: 'DM Mono', monospace; font-size: 11px; }
.load-more { width: calc(100% - 28px); min-height: 44px; display: flex; align-items: center; justify-content: center; gap: 6px; margin: 14px; color: var(--pine); background: #edf1eb; border: 1px solid var(--line); border-radius: 7px; cursor: pointer; font-size: 10px; font-weight: 700; }
.event-skeleton { margin: 0; padding: 0; list-style: none; }
.event-skeleton li { height: 110px; padding: 20px; border-bottom: 1px solid var(--line); }
.event-skeleton i, .event-skeleton span { display: block; background: linear-gradient(90deg,#e6e9e3,#f3f4ef,#e6e9e3); background-size: 200% 100%; animation: shimmer 1.4s infinite; border-radius: 30px; }
.event-skeleton i { float: left; width: 52px; height: 52px; margin-right: 14px; }
.event-skeleton span { height: 10px; margin: 5px 0 12px; }
.event-skeleton span:last-child { width: 56%; height: 7px; }
@keyframes shimmer { to { background-position: -200% 0; } }
.stream-empty { display: flex; min-height: 500px; flex-direction: column; align-items: center; justify-content: center; padding: 30px; text-align: center; }
.stream-empty > svg { width: 34px; height: 34px; color: var(--mineral); }
.stream-empty h3 { margin: 16px 0 6px; font-family: 'Newsreader', serif; font-size: 23px; }
.stream-empty p { max-width: 280px; margin: 0; color: var(--muted); font-size: 11px; line-height: 1.6; }

.event-detail { position: absolute; z-index: 800; top: 0; right: 0; width: min(480px, 42vw); height: 100%; padding: 20px 24px 28px; overflow-y: auto; background: rgba(255,254,250,.985); border-left: 1px solid var(--line-strong); box-shadow: -18px 0 45px rgba(20,40,34,.17); animation: detail-in .2s ease-out; }
@keyframes detail-in { from { opacity: 0; transform: translateX(20px); } }
.detail-topline { display: flex; align-items: center; justify-content: space-between; color: var(--muted); font-family: 'DM Mono', monospace; font-size: 8px; text-transform: uppercase; }
.detail-hero { display: grid; grid-template-columns: 100px 1fr; gap: 20px; align-items: center; padding: 22px 0; border-bottom: 1px solid var(--line); }
.detail-magnitude { width: 94px; height: 94px; display: flex; flex-direction: column; align-items: center; justify-content: center; background: #faf7ef; border: 4px solid var(--depth-shallow); border-radius: 50%; }
.detail-magnitude.depth-intermediate { border-color: var(--depth-mid); }
.detail-magnitude.depth-deep { border-color: var(--depth-deep); border-style: double; border-width: 7px; }
.detail-magnitude small, .detail-magnitude span { color: var(--muted); font-family: 'DM Mono', monospace; font-size: 7px; text-transform: uppercase; }
.detail-magnitude strong { font-family: 'Newsreader', serif; font-size: 40px; line-height: 1; }
.detail-hero h2 { margin: 0; font-family: 'Newsreader', Georgia, serif; font-size: 27px; font-weight: 600; line-height: 1.05; }
.detail-context { margin: 9px 0 0; color: var(--ink-soft); font-size: 10px; }
.assessment { display: flex; gap: 10px; margin: 16px 0; padding: 13px; color: #5c4a1e; background: #f5ead0; border-left: 4px solid var(--amber); border-radius: 4px; }
.assessment.alert-red, .assessment.alert-orange { color: #662b24; background: #f4dfdb; border-color: var(--alert-red); }
.assessment svg { flex: 0 0 auto; }
.assessment strong { font-size: 10px; line-height: 1.4; }
.assessment p { margin: 4px 0 0; font-size: 9px; line-height: 1.5; }
.detail-grid { display: grid; grid-template-columns: 1fr 1fr; margin: 0; border-top: 1px solid var(--line); border-left: 1px solid var(--line); }
.detail-grid > div { min-height: 74px; padding: 12px; border-right: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.detail-grid .coordinates { grid-column: auto; }
.detail-grid dt { margin-bottom: 6px; color: var(--muted); font-family: 'DM Mono', monospace; font-size: 7px; text-transform: uppercase; }
.detail-grid dd { margin: 0; font-size: 10px; line-height: 1.45; }
.detail-grid dd small { display: block; margin-top: 3px; color: var(--muted); font-size: 8px; }
.detail-notes { margin: 16px 0; border-top: 1px solid var(--line); }
.detail-notes details { padding: 11px 0; border-bottom: 1px solid var(--line); }
.detail-notes summary { cursor: pointer; font-size: 10px; font-weight: 700; }
.detail-notes p { margin: 8px 0 0; color: var(--ink-soft); font-size: 9px; line-height: 1.6; }
.primary-link { min-height: 48px; display: flex; align-items: center; justify-content: center; gap: 8px; color: white; background: var(--pine); border-radius: 7px; text-decoration: none; font-size: 11px; font-weight: 700; }
.primary-link:hover { background: var(--mineral); }
.sheet-backdrop { position: fixed; inset: 0; z-index: 3000; display: grid; place-items: center; padding: 20px; background: rgba(8,27,24,.55); backdrop-filter: blur(5px); }
.filter-sheet { width: min(560px, 100%); max-height: calc(100vh - 40px); padding: 24px; overflow-y: auto; background: var(--paper); border-radius: 14px; box-shadow: var(--shadow); }
.apply-filters { width: 100%; min-height: 48px; color: white; background: var(--pine); border: 0; border-radius: 7px; cursor: pointer; font-weight: 700; }
footer { display: flex; justify-content: space-between; gap: 20px; padding: 18px clamp(24px, 4vw, 64px) 32px; color: var(--muted); border-top: 1px solid var(--line); font-family: 'DM Mono', monospace; font-size: 8px; }
footer a { display: inline-flex; align-items: center; gap: 3px; color: var(--pine); }
footer svg { width: 10px; height: 10px; }

@media (max-width: 1180px) {
  .explorer { grid-template-columns: 0 minmax(420px, 1fr) 350px; }
  .filters-column { display: none; }
  .map-toolbar button:first-child { display: inline-flex; }
  .observation-header { grid-template-columns: 1fr; gap: 34px; }
  .field-summary { max-width: 900px; }
}

@media (min-width: 1181px) {
  .map-toolbar button:first-child { display: none; }
}

@media (max-width: 800px) {
  .site-header { height: auto; min-height: 66px; grid-template-columns: 1fr auto; gap: 10px; padding: 10px 14px; }
  .brand small { display: none; }
  .brand strong { font-size: 18px; }
  .brand-mark { width: 34px; height: 34px; }
  .time-tabs { grid-column: 1 / -1; grid-row: 2; width: 100%; order: 3; }
  .time-tabs button { flex: 1; min-width: 0; }
  .header-actions { grid-column: 2; grid-row: 1; }
  .header-button { width: 44px; padding: 0; justify-content: center; }
  .header-button span { position: absolute; clip: rect(0 0 0 0); }
  .data-status { justify-content: flex-start; overflow-x: auto; white-space: nowrap; padding: 7px 14px; }
  .data-status > span:nth-of-type(2) { display: none; }
  .observation-header { padding: 30px 18px 26px; }
  .observation-copy h1 { font-size: clamp(42px, 13vw, 60px); }
  .observation-copy > p:last-child { font-size: 13px; }
  .field-summary { grid-template-columns: 1fr 1fr; }
  .field-summary > div { min-height: 100px; padding: 16px 12px; border-bottom: 1px solid var(--line); }
  .field-summary > div:nth-child(3) { border-left: 0; }
  .field-summary small { margin-bottom: 10px; }
  .timeline { margin: 0 12px 14px; padding: 16px 14px 12px; border-radius: 9px; }
  .timeline-heading { display: block; }
  .timeline-readout { margin-top: 7px; }
  .seismic-ribbon { gap: 1px; }
  .timeline-axis { margin-left: 47px; }
  .mobile-view-switch { position: sticky; top: 120px; z-index: 900; display: grid; grid-template-columns: 1fr 1fr; gap: 4px; margin: 0 12px 8px; padding: 4px; background: #dde4dd; border: 1px solid var(--line); border-radius: 9px; }
  .mobile-view-switch button { min-height: 44px; display: flex; align-items: center; justify-content: center; gap: 7px; background: transparent; border: 0; border-radius: 6px; cursor: pointer; font-size: 11px; font-weight: 700; }
  .mobile-view-switch button.is-active { color: white; background: var(--pine); }
  .mobile-view-switch span { padding: 2px 5px; background: rgba(255,255,255,.15); border-radius: 8px; font-family: 'DM Mono', monospace; font-size: 7px; }
  .explorer { display: block; min-height: 570px; margin: 0 0 20px; border-right: 0; border-left: 0; border-radius: 0; box-shadow: none; }
  .map-column, .stream-column { display: none; }
  .map-column.is-mobile-active, .stream-column.is-mobile-active { display: block; }
  .map-column, .map-shell, .map-canvas { min-height: calc(100svh - 180px); height: calc(100svh - 180px); }
  .stream-column { max-height: none; min-height: 600px; border-left: 0; }
