.timeline { margin: 0 clamp(24px, 4vw, 64px) 26px; padding: 20px 24px 15px; background: #ecf0e9; border: 1px solid var(--line); border-radius: 12px; box-shadow: inset 0 1px rgba(255,255,255,.7); }
