.quake-marker { display: grid!important; place-items: center; color: var(--ink); background: rgba(255,254,250,.92); border: 3px solid var(--depth-shallow); border-radius: 50%; box-shadow: 0 0 0 2px rgba(255,254,250,.8), 0 5px 12px rgba(24,42,36,.22); font-family: 'DM Mono', monospace; font-size: 10px; font-weight: 500; transition: opacity .15s, transform .15s, box-shadow .15s; }
.quake-marker.depth-intermediate { border-color: var(--depth-mid); }
