.contour-loader i:nth-child(3) { inset: 5px; opacity: .25; animation-delay: .4s; }
@keyframes pulse { 50% { transform: scale(1.1) rotate(8deg); } }

.stream-column { min-width: 0; max-height: 720px; overflow-y: auto; background: var(--paper-raised); border-left: 1px solid var(--line); scrollbar-color: #aeb8ae transparent; scrollbar-width: thin; }
.stream-heading { position: sticky; top: 0; z-index: 10; display: flex; align-items: flex-end; justify-content: space-between; gap: 12px; padding: 20px 18px 14px; background: rgba(255,254,250,.96); border-bottom: 1px solid var(--line); backdrop-filter: blur(12px); }
.stream-heading h2 { margin: 0; font-family: 'Newsreader', Georgia, serif; font-size: 26px; }
.stream-heading label { color: var(--muted); font-family: 'DM Mono', monospace; font-size: 8px; text-transform: uppercase; }
.stream-heading select { display: block; width: 118px; min-height: 36px; margin-top: 4px; }
.active-filters { display: flex; gap: 6px; padding: 10px 14px; overflow-x: auto; border-bottom: 1px solid var(--line); }
.active-filters button { flex: 0 0 auto; min-height: 30px; display: flex; align-items: center; gap: 4px; padding: 0 8px; color: var(--pine); background: #e3ece7; border: 1px solid #bbcbc2; border-radius: 15px; cursor: pointer; font-size: 8px; }
.active-filters button svg { width: 11px; }
.active-filters .clear-all { color: var(--copper); background: transparent; border-color: transparent; }
.event-list { margin: 0; padding: 0; list-style: none; }
.event-row { width: 100%; min-height: 112px; display: grid; grid-template-columns: 55px minmax(0, 1fr) 38px; gap: 12px; align-items: center; padding: 14px 16px; text-align: left; background: transparent; border: 0; border-bottom: 1px solid #dde1dc; cursor: pointer; transition: background .12s, opacity .12s; }
.event-row:hover { background: #f0f3ed; }
.event-row.is-selected { background: #e4ece7; box-shadow: inset 4px 0 var(--pine); }
.event-row.is-muted { opacity: .3; }
.event-mag { width: 52px; height: 52px; display: flex; flex-direction: column; align-items: center; justify-content: center; background: #faf7ef; border: 2px solid var(--depth-shallow); border-radius: 50%; }
.event-mag.depth-intermediate { border-color: var(--depth-mid); }
.event-mag.depth-deep { border-color: var(--depth-deep); border-style: double; border-width: 4px; }
.event-mag b { font-family: 'Newsreader', serif; font-size: 22px; font-weight: 600; line-height: 1; }
.event-mag small { margin-top: 3px; color: var(--muted); font-family: 'DM Mono', monospace; font-size: 7px; }
.event-copy { min-width: 0; display: block; }
.event-copy > strong { display: -webkit-box; overflow: hidden; color: var(--ink); font-size: 11px; line-height: 1.4; -webkit-line-clamp: 2; -webkit-box-orient: vertical; }
.event-copy > span:not(.event-tags) { display: flex; align-items: center; gap: 4px; margin-top: 7px; color: var(--muted); font-family: 'DM Mono', monospace; font-size: 8px; }
.event-copy > span svg { width: 11px; height: 11px; }
.event-copy > span i { width: 2px; height: 2px; margin: 0 2px; background: var(--line-strong); border-radius: 50%; }
.event-tags { display: flex; flex-wrap: wrap; gap: 4px; margin-top: 7px; }
.status-tag { display: inline-flex; align-items: center; gap: 3px; padding: 3px 5px; color: #486057; background: #e6ece8; border-radius: 3px; font-family: 'DM Mono', monospace; font-size: 6px; font-style: normal; font-weight: 500; text-transform: uppercase; }
.status-tag svg { width: 9px!important; height: 9px!important; }
.status-tag.alert-yellow { color: #68480d; background: #f8e4aa; }
.status-tag.alert-orange, .status-tag.alert-red { color: white; background: #a94d38; }
.status-tag.tsunami { color: #31576c; background: #dbe9ef; }
.event-sig { text-align: right; }
.event-sig small { display: block; color: var(--muted); font-family: 'DM Mono', monospace; font-size: 7px; }
.event-sig b { font-family: 'DM Mono', monospace; font-size: 11px; }
.load-more { width: calc(100% - 28px); min-height: 44px; display: flex; align-items: center; justify-content: center; gap: 6px; margin: 14px; color: var(--pine); background: #edf1eb; border: 1px solid var(--line); border-radius: 7px; cursor: pointer; font-size: 10px; font-weight: 700; }
.event-skeleton { margin: 0; padding: 0; list-style: none; }
.event-skeleton li { height: 110px; padding: 20px; border-bottom: 1px solid var(--line); }
.event-skeleton i, .event-skeleton span { display: block; background: linear-gradient(90deg,#e6e9e3,#f3f4ef,#e6e9e3); background-size: 200% 100%; animation: shimmer 1.4s infinite; border-radius: 30px; }
.event-skeleton i { float: left; width: 52px; height: 52px; margin-right: 14px; }
.event-skeleton span { height: 10px; margin: 5px 0 12px; }
.event-skeleton span:last-child { width: 56%; height: 7px; }
@keyframes shimmer { to { background-position: -200% 0; } }
.stream-empty { display: flex; min-height: 500px; flex-direction: column; align-items: center; justify-content: center; padding: 30px; text-align: center; }
.stream-empty > svg { width: 34px; height: 34px; color: var(--mineral); }
.stream-empty h3 { margin: 16px 0 6px; font-family: 'Newsreader', serif; font-size: 23px; }
.stream-empty p { max-width: 280px; margin: 0; color: var(--muted); font-size: 11px; line-height: 1.6; }

.event-detail { position: absolute; z-index: 800; top: 0; right: 0; width: min(480px, 42vw); height: 100%; padding: 20px 24px 28px; overflow-y: auto; background: rgba(255,254,250,.985); border-left: 1px solid var(--line-strong); box-shadow: -18px 0 45px rgba(20,40,34,.17); animation: detail-in .2s ease-out; }
@keyframes detail-in { from { opacity: 0; transform: translateX(20px); } }
.detail-topline { display: flex; align-items: center; justify-content: space-between; color: var(--muted); font-family: 'DM Mono', monospace; font-size: 8px; text-transform: uppercase; }
.detail-hero { display: grid; grid-template-columns: 100px 1fr; gap: 20px; align-items: center; padding: 22px 0; border-bottom: 1px solid var(--line); }
.detail-magnitude { width: 94px; height: 94px; display: flex; flex-direction: column; align-items: center; justify-content: center; background: #faf7ef; border: 4px solid var(--depth-shallow); border-radius: 50%; }
.detail-magnitude.depth-intermediate { border-color: var(--depth-mid); }
.detail-magnitude.depth-deep { border-color: var(--depth-deep); border-style: double; border-width: 7px; }
.detail-magnitude small, .detail-magnitude span { color: var(--muted); font-family: 'DM Mono', monospace; font-size: 7px; text-transform: uppercase; }
.detail-magnitude strong { font-family: 'Newsreader', serif; font-size: 40px; line-height: 1; }
.detail-hero h2 { margin: 0; font-family: 'Newsreader', Georgia, serif; font-size: 27px; font-weight: 600; line-height: 1.05; }
.detail-context { margin: 9px 0 0; color: var(--ink-soft); font-size: 10px; }
.assessment { display: flex; gap: 10px; margin: 16px 0; padding: 13px; color: #5c4a1e; background: #f5ead0; border-left: 4px solid var(--amber); border-radius: 4px; }
.assessment.alert-red, .assessment.alert-orange { color: #662b24; background: #f4dfdb; border-color: var(--alert-red); }
.assessment svg { flex: 0 0 auto; }
.assessment strong { font-size: 10px; line-height: 1.4; }
.assessment p { margin: 4px 0 0; font-size: 9px; line-height: 1.5; }
.detail-grid { display: grid; grid-template-columns: 1fr 1fr; margin: 0; border-top: 1px solid var(--line); border-left: 1px solid var(--line); }
.detail-grid > div { min-height: 74px; padding: 12px; border-right: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.detail-grid .coordinates { grid-column: auto; }
.detail-grid dt { margin-bottom: 6px; color: var(--muted); font-family: 'DM Mono', monospace; font-size: 7px; text-transform: uppercase; }
.detail-grid dd { margin: 0; font-size: 10px; line-height: 1.45; }
.detail-grid dd small { display: block; margin-top: 3px; color: var(--muted); font-size: 8px; }
.detail-notes { margin: 16px 0; border-top: 1px solid var(--line); }
.detail-notes details { padding: 11px 0; border-bottom: 1px solid var(--line); }
.detail-notes summary { cursor: pointer; font-size: 10px; font-weight: 700; }
.detail-notes p { margin: 8px 0 0; color: var(--ink-soft); font-size: 9px; line-height: 1.6; }
.primary-link { min-height: 48px; display: flex; align-items: center; justify-content: center; gap: 8px; color: white; background: var(--pine); border-radius: 7px; text-decoration: none; font-size: 11px; font-weight: 700; }
.primary-link:hover { background: var(--mineral); }
.sheet-backdrop { position: fixed; inset: 0; z-index: 3000; display: grid; place-items: center; padding: 20px; background: rgba(8,27,24,.55); backdrop-filter: blur(5px); }
.filter-sheet { width: min(560px, 100%); max-height: calc(100vh - 40px); padding: 24px; overflow-y: auto; background: var(--paper); border-radius: 14px; box-shadow: var(--shadow); }
.apply-filters { width: 100%; min-height: 48px; color: white; background: var(--pine); border: 0; border-radius: 7px; cursor: pointer; font-weight: 700; }
footer { display: flex; justify-content: space-between; gap: 20px; padding: 18px clamp(24px, 4vw, 64px) 32px; color: var(--muted); border-top: 1px solid var(--line); font-family: 'DM Mono', monospace; font-size: 8px; }
footer a { display: inline-flex; align-items: center; gap: 3px; color: var(--pine); }
footer svg { width: 10px; height: 10px; }

@media (max-width: 1180px) {
  .explorer { grid-template-columns: 0 minmax(420px, 1fr) 350px; }
  .filters-column { display: none; }
  .map-toolbar button:first-child { display: inline-flex; }
  .observation-header { grid-template-columns: 1fr; gap: 34px; }
  .field-summary { max-width: 900px; }
}

@media (min-width: 1181px) {
  .map-toolbar button:first-child { display: none; }
}

@media (max-width: 800px) {
  .site-header { height: auto; min-height: 66px; grid-template-columns: 1fr auto; gap: 10px; padding: 10px 14px; }
  .brand small { display: none; }
  .brand strong { font-size: 18px; }
  .brand-mark { width: 34px; height: 34px; }
  .time-tabs { grid-column: 1 / -1; grid-row: 2; width: 100%; order: 3; }
  .time-tabs button { flex: 1; min-width: 0; }
  .header-actions { grid-column: 2; grid-row: 1; }
  .header-button { width: 44px; padding: 0; justify-content: center; }
  .header-button span { position: absolute; clip: rect(0 0 0 0); }
  .data-status { justify-content: flex-start; overflow-x: auto; white-space: nowrap; padding: 7px 14px; }
  .data-status > span:nth-of-type(2) { display: none; }
  .observation-header { padding: 30px 18px 26px; }
  .observation-copy h1 { font-size: clamp(42px, 13vw, 60px); }
  .observation-copy > p:last-child { font-size: 13px; }
  .field-summary { grid-template-columns: 1fr 1fr; }
  .field-summary > div { min-height: 100px; padding: 16px 12px; border-bottom: 1px solid var(--line); }
  .field-summary > div:nth-child(3) { border-left: 0; }
  .field-summary small { margin-bottom: 10px; }
  .timeline { margin: 0 12px 14px; padding: 16px 14px 12px; border-radius: 9px; }
  .timeline-heading { display: block; }
  .timeline-readout { margin-top: 7px; }
  .seismic-ribbon { gap: 1px; }
  .timeline-axis { margin-left: 47px; }
  .mobile-view-switch { position: sticky; top: 120px; z-index: 900; display: grid; grid-template-columns: 1fr 1fr; gap: 4px; margin: 0 12px 8px; padding: 4px; background: #dde4dd; border: 1px solid var(--line); border-radius: 9px; }
  .mobile-view-switch button { min-height: 44px; display: flex; align-items: center; justify-content: center; gap: 7px; background: transparent; border: 0; border-radius: 6px; cursor: pointer; font-size: 11px; font-weight: 700; }
  .mobile-view-switch button.is-active { color: white; background: var(--pine); }
  .mobile-view-switch span { padding: 2px 5px; background: rgba(255,255,255,.15); border-radius: 8px; font-family: 'DM Mono', monospace; font-size: 7px; }
  .explorer { display: block; min-height: 570px; margin: 0 0 20px; border-right: 0; border-left: 0; border-radius: 0; box-shadow: none; }
  .map-column, .stream-column { display: none; }
  .map-column.is-mobile-active, .stream-column.is-mobile-active { display: block; }
  .map-column, .map-shell, .map-canvas { min-height: calc(100svh - 180px); height: calc(100svh - 180px); }
  .stream-column { max-height: none; min-height: 600px; border-left: 0; }
  .stream-heading { top: 0; }
  .map-toolbar { top: 10px; left: 10px; right: 10px; overflow-x: auto; }
  .map-toolbar button { flex: 0 0 auto; }
  .map-key { bottom: 10px; left: 10px; max-width: calc(100% - 80px); }
  .map-key .key-note { display: none; }
  .event-detail { position: fixed; inset: 0; z-index: 2500; width: 100%; height: 100%; padding: 18px 18px 34px; border: 0; animation: detail-up .22s ease-out; }
  @keyframes detail-up { from { opacity: 0; transform: translateY(28px); } }
  .detail-hero { grid-template-columns: 86px 1fr; gap: 14px; }
  .detail-magnitude { width: 82px; height: 82px; }
  .detail-hero h2 { font-size: 24px; }
  .filter-sheet { align-self: end; width: 100%; max-height: 91vh; padding: 20px 18px max(20px, env(safe-area-inset-bottom)); border-radius: 18px 18px 0 0; }
  .sheet-backdrop { place-items: end center; padding: 0; }
  footer { display: block; padding: 18px; line-height: 1.7; }
}

@media (max-width: 420px) {
  .field-summary strong { font-size: 28px; }
  .field-summary span { font-size: 9px; }
  .map-toolbar button { width: 44px; padding: 0; justify-content: center; }
  .map-toolbar button svg { margin: 0; }
  .map-toolbar button:not(:first-child) { font-size: 0; }
  .map-toolbar button:not(:first-child) svg { width: 18px; height: 18px; }
  .event-row { grid-template-columns: 52px minmax(0, 1fr) 34px; gap: 10px; padding: 13px 12px; }
  .detail-grid { grid-template-columns: 1fr 1fr; }
  .timeline h2 { font-size: 19px; }
  .timeline-readout > span:first-child { font-size: 9px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto!important; animation-duration: .01ms!important; animation-iteration-count: 1!important; transition-duration: .01ms!important; }
}

@media (forced-colors: active) {
  .quake-marker, .event-mag, .detail-magnitude { border-style: solid!important; }
  .quake-marker.depth-deep, .event-mag.depth-deep, .detail-magnitude.depth-deep { outline: 2px dotted CanvasText; outline-offset: 2px; }
  .quake-marker.is-selected { outline: 4px double Highlight; }
  .seismic-ribbon > span { border: 1px solid CanvasText; }
}

