import { useEffect, useRef } from 'react'
import L from 'leaflet'
import 'leaflet/dist/leaflet.css'
import 'leaflet.markercluster'
import 'leaflet.markercluster/dist/MarkerCluster.css'
import 'leaflet.markercluster/dist/MarkerCluster.Default.css'
import type { EarthquakeFeature, MapBounds } from './types'
import { depthBand, formatMagnitude } from './data'

interface MapViewProps {
  events: EarthquakeFeature[]
  selectedId: string | null
  highlightedIds: Set<string> | null
  onSelect: (event: EarthquakeFeature) => void
  onHover: (id: string | null) => void
  hoveredId: string | null
  onBoundsChange: (bounds: MapBounds) => void
  fitSignal: number
}

function markerSize(magnitude: number | null) {
  const value = Math.max(0, magnitude ?? 0)
  return Math.round(Math.min(54, Math.max(24, 20 + value * 4.2)))
}

function markerClass(event: EarthquakeFeature, selectedId: string | null, hoveredId: string | null, highlightedIds: Set<string> | null) {
  const magnitude = event.properties.mag ?? 0
  const depth = event.geometry.coordinates[2]
  const classes = ['quake-marker', `depth-${depthBand(depth).toLowerCase()}`]
  if (magnitude >= 6) classes.push('magnitude-major')
  else if (magnitude >= 4.5) classes.push('magnitude-notable')
  else classes.push('magnitude-routine')
  if (event.properties.alert) classes.push(`alert-${event.properties.alert}`)
  if (event.properties.tsunami === 1) classes.push('has-tsunami')
  if (event.id === selectedId) classes.push('is-selected')
  if (event.id === hoveredId) classes.push('is-hovered')
  if (highlightedIds && !highlightedIds.has(event.id)) classes.push('is-muted')
  return classes.join(' ')
}

export function MapView({ events, selectedId, highlightedIds, onSelect, onHover, hoveredId, onBoundsChange, fitSignal }: MapViewProps) {
  const containerRef = useRef<HTMLDivElement>(null)
  const mapRef = useRef<L.Map | null>(null)
  const clusterRef = useRef<L.MarkerClusterGroup | null>(null)
  const markerRefs = useRef(new Map<string, L.Marker>())
  const onBoundsRef = useRef(onBoundsChange)
  onBoundsRef.current = onBoundsChange

  useEffect(() => {
    if (!containerRef.current || mapRef.current) return
    const map = L.map(containerRef.current, {
      center: [18, 4],
      zoom: 2,
      minZoom: 2,
      maxZoom: 11,
      worldCopyJump: true,
      zoomControl: false,
      attributionControl: true,
    })
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19,
      attribution: '&copy; OpenStreetMap contributors',
    }).addTo(map)
    L.control.zoom({ position: 'bottomright' }).addTo(map)

    const cluster = L.markerClusterGroup({
      showCoverageOnHover: false,
      spiderfyOnMaxZoom: true,
      spiderfyDistanceMultiplier: 1.8,
      maxClusterRadius: 46,
      removeOutsideVisibleBounds: true,
      iconCreateFunction: (group) => {
        const children = group.getAllChildMarkers()
        const maxMagnitude = Math.max(...children.map((marker) => Number(marker.options.title) || 0))
        return L.divIcon({
          html: `<span class="cluster-count">${group.getChildCount()}</span><span class="cluster-mag">M${maxMagnitude.toFixed(1)} max</span>`,
          className: `quake-cluster ${maxMagnitude >= 5 ? 'cluster-notable' : ''}`,
          iconSize: L.point(58, 58),
        })
      },
    })
    map.addLayer(cluster)
    mapRef.current = map
    clusterRef.current = cluster

    const reportBounds = () => {
      const bounds = map.getBounds()
      onBoundsRef.current({ north: bounds.getNorth(), south: bounds.getSouth(), east: bounds.getEast(), west: bounds.getWest() })
    }
    map.on('moveend', reportBounds)
    reportBounds()

    return () => {
      map.off('moveend', reportBounds)
      map.remove()
      mapRef.current = null
      clusterRef.current = null
    }
  }, [])

  useEffect(() => {
    const cluster = clusterRef.current
    if (!cluster) return
    cluster.clearLayers()
    markerRefs.current.clear()

    events.forEach((event) => {
      const [longitude, latitude] = event.geometry.coordinates
      const size = markerSize(event.properties.mag)
      const icon = L.divIcon({
        html: `<span aria-hidden="true">${formatMagnitude(event.properties.mag)}</span>`,
        className: markerClass(event, selectedId, hoveredId, highlightedIds),
        iconSize: L.point(size, size),
        iconAnchor: L.point(size / 2, size / 2),
      })
      const marker = L.marker([latitude, longitude], {
        icon,
        title: String(event.properties.mag ?? 0),
        alt: `${event.properties.title}, ${event.geometry.coordinates[2]} kilometers deep`,
        keyboard: true,
        riseOnHover: true,
      })
      marker.bindTooltip(`<strong>${event.properties.title}</strong><br>${event.geometry.coordinates[2].toFixed(1)} km deep`, {
        direction: 'top',
        offset: [0, -size / 2],
      })
      marker.on('click', () => onSelect(event))
      marker.on('mouseover focus', () => onHover(event.id))
      marker.on('mouseout blur', () => onHover(null))
      markerRefs.current.set(event.id, marker)
      cluster.addLayer(marker)
    })
  }, [events, selectedId, hoveredId, highlightedIds, onSelect, onHover])

  useEffect(() => {
    if (!selectedId) return
    const map = mapRef.current
    const marker = markerRefs.current.get(selectedId)
    const cluster = clusterRef.current
    if (!map || !marker || !cluster) return
    cluster.zoomToShowLayer(marker, () => {
      map.panTo(marker.getLatLng(), { animate: !window.matchMedia('(prefers-reduced-motion: reduce)').matches })
      marker.openTooltip()
    })
  }, [selectedId])

  useEffect(() => {
    const map = mapRef.current
    if (!map || events.length === 0 || fitSignal === 0) return
    const bounds = L.latLngBounds(events.map((event) => [event.geometry.coordinates[1], event.geometry.coordinates[0]] as L.LatLngTuple))
    map.fitBounds(bounds, { padding: [48, 48], maxZoom: 6, animate: !window.matchMedia('(prefers-reduced-motion: reduce)').matches })
  }, [fitSignal, events])

  return (
    <div className="map-shell" aria-label="Interactive map of filtered earthquakes">
      <div ref={containerRef} className="map-canvas" />
      <div className="map-key" aria-hidden="true">
        <span><i className="key-shallow" /> Shallow</span>
        <span><i className="key-intermediate" /> Intermediate</span>
        <span><i className="key-deep" /> Deep</span>
        <span className="key-note">Marker size shows magnitude</span>
      </div>
    </div>
  )
}

import { useEffect, useMemo, useState } from 'react'
import type { EarthquakeFeature, TimeRange } from './types'
import { RANGE_LABELS, RANGE_MS, formatDateTime } from './data'

interface TimelineProps {
  events: EarthquakeFeature[]
  range: TimeRange
  selectedEvent: EarthquakeFeature | null
  onHighlight: (ids: Set<string> | null) => void
}

const BIN_COUNT = 48

export function Timeline({ events, range, selectedEvent, onHighlight }: TimelineProps) {
  const [activeBin, setActiveBin] = useState<number | null>(null)
  const now = useMemo(() => Date.now(), [events, range])
  const start = now - RANGE_MS[range]
  const binWidth = RANGE_MS[range] / BIN_COUNT

  const bins = useMemo(() => {
    const result = Array.from({ length: BIN_COUNT }, (_, index) => ({ index, count: 0, maxMagnitude: -1, ids: [] as string[] }))
    events.forEach((event) => {
      const index = Math.min(BIN_COUNT - 1, Math.max(0, Math.floor((event.properties.time - start) / binWidth)))
      const bin = result[index]
      bin.count += 1
      bin.maxMagnitude = Math.max(bin.maxMagnitude, event.properties.mag ?? -1)
      bin.ids.push(event.id)
    })
    return result
  }, [events, start, binWidth])

  const maxCount = Math.max(1, ...bins.map((bin) => bin.count))
  const selectedBin = selectedEvent
    ? Math.min(BIN_COUNT - 1, Math.max(0, Math.floor((selectedEvent.properties.time - start) / binWidth)))
    : null
  const shownBin = activeBin ?? selectedBin

  useEffect(() => {
    if (activeBin == null) onHighlight(null)
    else onHighlight(new Set(bins[activeBin]?.ids ?? []))
  }, [activeBin, bins, onHighlight])

  const describeBin = (index: number) => {
    const from = start + index * binWidth
    const to = from + binWidth
    const bin = bins[index]
    return `${bin.count} earthquake${bin.count === 1 ? '' : 's'} between ${formatDateTime(from)} and ${formatDateTime(to)}${bin.maxMagnitude >= 0 ? `; strongest magnitude ${bin.maxMagnitude.toFixed(1)}` : ''}`
  }

  return (
    <section className="timeline" aria-labelledby="timeline-title">
      <div className="timeline-heading">
        <div>
          <p className="eyebrow">Connected seismic timeline</p>
          <h2 id="timeline-title">Activity through {RANGE_LABELS[range].toLowerCase()}</h2>
        </div>
        <div className="timeline-readout" aria-live="polite">
          {activeBin == null ? (
            <span>Slide the time lens to isolate a moment</span>
          ) : (
            <>
              <strong>{bins[activeBin].count}</strong>
              <span>events in focus</span>
              <button type="button" onClick={() => setActiveBin(null)}>Show all</button>
            </>
          )}
        </div>
      </div>
      <div className="seismic-ribbon" aria-hidden="true">
        {bins.map((bin) => {
          const height = 6 + (bin.count / maxCount) * 42
          return (
            <span
              key={bin.index}
              className={`${shownBin === bin.index ? 'is-active' : ''} ${bin.maxMagnitude >= 5 ? 'has-notable' : ''}`}
              style={{ height: `${height}px` }}
            />
          )
        })}
        {shownBin != null && <i className="timeline-needle" style={{ left: `${((shownBin + 0.5) / BIN_COUNT) * 100}%` }} />}
      </div>
      <label className="timeline-slider-label" htmlFor="time-lens">
        <span>Earlier</span>
        <span className="sr-only">Time lens. {activeBin == null ? 'All events are visible.' : describeBin(activeBin)}</span>
        <input
          id="time-lens"
          type="range"
          min="0"
          max={BIN_COUNT - 1}
          value={activeBin ?? selectedBin ?? BIN_COUNT - 1}
          onChange={(event) => setActiveBin(Number(event.target.value))}
          aria-valuetext={describeBin(activeBin ?? selectedBin ?? BIN_COUNT - 1)}
        />
        <span>Now</span>
      </label>
      <div className="timeline-axis" aria-hidden="true">
        <span>{new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric', hour: range === 'hour' || range === 'day' ? 'numeric' : undefined }).format(start)}</span>
        <span>{new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric', hour: 'numeric' }).format(now)}</span>
      </div>
      <details className="timeline-table">
        <summary>Read activity as text</summary>
        <ol>
          {bins.filter((bin) => bin.count > 0).map((bin) => <li key={bin.index}>{describeBin(bin.index)}</li>)}
        </ol>
      </details>
    </section>
  )
}

import type { EarthquakeFeature, EarthquakeFeed, FilterState, MapBounds, TimeRange } from './types'

export const FEEDS: Record<TimeRange, string> = {
  hour: 'https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/all_hour.geojson',
  day: 'https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/all_day.geojson',
  week: 'https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/all_week.geojson',
  month: 'https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/all_month.geojson',
}

export const RANGE_LABELS: Record<TimeRange, string> = {
  hour: 'Past hour',
  day: 'Past 24 hours',
  week: 'Past 7 days',
  month: 'Past 30 days',
}

export const RANGE_MS: Record<TimeRange, number> = {
  hour: 60 * 60 * 1000,
  day: 24 * 60 * 60 * 1000,
  week: 7 * 24 * 60 * 60 * 1000,
  month: 30 * 24 * 60 * 60 * 1000,
}

export const DEFAULT_FILTERS: FilterState = {
  range: 'week',
  minMagnitude: 2.5,
  depth: 'all',
  alert: 'all',
  tsunami: 'all',
  status: 'all',
  query: '',
  sort: 'significance',
  area: 'world',
}

export function parseUrlState(): { filters: FilterState; selectedId: string | null } {
  const params = new URLSearchParams(window.location.search)
  const range = params.get('range')
  const depth = params.get('depth')
  const alert = params.get('alert')
  const tsunami = params.get('tsunami')
  const status = params.get('status')
  const sort = params.get('sort')
  const area = params.get('area')
  const magnitude = Number(params.get('mag'))

  return {
    filters: {
      range: range === 'hour' || range === 'day' || range === 'month' ? range : 'week',
      minMagnitude: Number.isFinite(magnitude) && magnitude >= -1 && magnitude <= 10 ? magnitude : DEFAULT_FILTERS.minMagnitude,
      depth: depth === 'shallow' || depth === 'intermediate' || depth === 'deep' ? depth : 'all',
      alert: alert === 'green' || alert === 'yellow' || alert === 'orange' || alert === 'red' || alert === 'none' ? alert : 'all',
      tsunami: tsunami === 'yes' || tsunami === 'no' ? tsunami : 'all',
      status: status === 'reviewed' || status === 'automatic' ? status : 'all',
      query: params.get('q') ?? '',
      sort: sort === 'magnitude' || sort === 'newest' || sort === 'depth' ? sort : 'significance',
      area: area === 'viewport' ? 'viewport' : 'world',
    },
    selectedId: params.get('event'),
  }
}

export function writeUrlState(filters: FilterState, selectedId: string | null) {
  const params = new URLSearchParams()
  if (filters.range !== DEFAULT_FILTERS.range) params.set('range', filters.range)
  if (filters.minMagnitude !== DEFAULT_FILTERS.minMagnitude) params.set('mag', String(filters.minMagnitude))
  if (filters.depth !== 'all') params.set('depth', filters.depth)
  if (filters.alert !== 'all') params.set('alert', filters.alert)
  if (filters.tsunami !== 'all') params.set('tsunami', filters.tsunami)
  if (filters.status !== 'all') params.set('status', filters.status)
  if (filters.query) params.set('q', filters.query)
  if (filters.sort !== DEFAULT_FILTERS.sort) params.set('sort', filters.sort)
  if (filters.area !== 'world') params.set('area', filters.area)
  if (selectedId) params.set('event', selectedId)
  const query = params.toString()
  window.history.replaceState(null, '', `${window.location.pathname}${query ? `?${query}` : ''}`)
}

export function inBounds(event: EarthquakeFeature, bounds: MapBounds | null) {
  if (!bounds) return true
  const [longitude, latitude] = event.geometry.coordinates
  const longitudeMatches = bounds.west <= bounds.east
    ? longitude >= bounds.west && longitude <= bounds.east
    : longitude >= bounds.west || longitude <= bounds.east
  return latitude >= bounds.south && latitude <= bounds.north && longitudeMatches
}

export function filterEvents(events: EarthquakeFeature[], filters: FilterState, bounds: MapBounds | null) {
  const query = filters.query.trim().toLocaleLowerCase()
  const filtered = events.filter((event) => {
    const magnitude = event.properties.mag ?? -10
    const depth = event.geometry.coordinates[2]
    const alert = event.properties.alert ?? 'none'
    const reviewed = event.properties.status.toLowerCase() === 'reviewed'

    if (magnitude < filters.minMagnitude) return false
    if (filters.depth === 'shallow' && depth >= 70) return false
    if (filters.depth === 'intermediate' && (depth < 70 || depth >= 300)) return false
    if (filters.depth === 'deep' && depth < 300) return false
    if (filters.alert !== 'all' && alert !== filters.alert) return false
    if (filters.tsunami === 'yes' && event.properties.tsunami !== 1) return false
    if (filters.tsunami === 'no' && event.properties.tsunami === 1) return false
    if (filters.status === 'reviewed' && !reviewed) return false
    if (filters.status === 'automatic' && reviewed) return false
    if (query && !(event.properties.place ?? event.properties.title).toLocaleLowerCase().includes(query)) return false
    if (filters.area === 'viewport' && !inBounds(event, bounds)) return false
    return true
  })

  return filtered.sort((a, b) => {
    if (filters.sort === 'magnitude') return (b.properties.mag ?? -10) - (a.properties.mag ?? -10)
    if (filters.sort === 'newest') return b.properties.time - a.properties.time
    if (filters.sort === 'depth') return b.geometry.coordinates[2] - a.geometry.coordinates[2]
    return b.properties.sig - a.properties.sig || (b.properties.mag ?? -10) - (a.properties.mag ?? -10)
  })
}

export function formatMagnitude(magnitude: number | null) {
  return magnitude == null ? '—' : magnitude.toFixed(1)
}

export function formatDepth(depth: number) {
  if (!Number.isFinite(depth)) return 'Depth unavailable'
  return `${depth < 10 ? depth.toFixed(1) : Math.round(depth)} km deep`
}

export function formatRelativeTime(timestamp: number, now = Date.now()) {
  const delta = Math.max(0, now - timestamp)
  const minutes = Math.floor(delta / 60_000)
  if (minutes < 1) return 'moments ago'
  if (minutes < 60) return `${minutes} min ago`
  const hours = Math.floor(minutes / 60)
  if (hours < 24) return `${hours} hr${hours === 1 ? '' : 's'} ago`
  const days = Math.floor(hours / 24)
  return `${days} day${days === 1 ? '' : 's'} ago`
}

export function formatDateTime(timestamp: number) {
  return new Intl.DateTimeFormat(undefined, {
    dateStyle: 'medium',
    timeStyle: 'long',
  }).format(timestamp)
}

export function formatUtc(timestamp: number) {
  return new Intl.DateTimeFormat('en', {
    month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit', second: '2-digit', timeZone: 'UTC', timeZoneName: 'short',
  }).format(timestamp)
}

export function magnitudeLabel(magnitude: number | null) {
  if (magnitude == null) return 'Magnitude unavailable'
  if (magnitude < 2.5) return 'Usually not felt'
  if (magnitude < 4) return 'Often felt nearby'
  if (magnitude < 5) return 'Light shaking possible'
  if (magnitude < 6) return 'Potentially damaging locally'
  if (magnitude < 7) return 'Strong earthquake'
  return 'Major earthquake'
}

export function depthBand(depth: number) {
  if (depth < 70) return 'Shallow'
  if (depth < 300) return 'Intermediate'
  return 'Deep'
}

export function percentileContext(event: EarthquakeFeature, events: EarthquakeFeature[]) {
  if (!events.length) return 'Context unavailable'
  const below = events.filter((item) => item.properties.sig < event.properties.sig).length
  const percentile = Math.max(1, Math.round((below / events.length) * 100))
  if (percentile >= 95) return `Among the most significant ${Math.max(1, 100 - percentile)}% in this view`
  if (percentile >= 75) return 'More significant than most events in this view'
  if (percentile >= 40) return 'Within the typical range for this view'
  return 'Lower significance than most events in this view'
}

export function loadCachedFeed(range: TimeRange): EarthquakeFeed | null {
  try {
    const raw = localStorage.getItem(`seismic-field:${range}`)
    return raw ? JSON.parse(raw) as EarthquakeFeed : null
  } catch {
    return null
  }
}

export function cacheFeed(range: TimeRange, feed: EarthquakeFeed) {
  try {
    localStorage.setItem(`seismic-field:${range}`, JSON.stringify(feed))
  } catch {
    // Storage may be unavailable; live data remains usable.
  }
}

  const fetchData = useCallback(async (range: TimeRange, background = false) => {
    abortRef.current?.abort()
    const controller = new AbortController()
    abortRef.current = controller
    background ? setRefreshing(true) : setLoading(true)
    setError(null)
    try {
      const response = await fetch(FEEDS[range], { signal: controller.signal, cache: 'no-store' })
      if (!response.ok) throw new Error(`USGS returned ${response.status}`)
      const nextFeed = await response.json() as EarthquakeFeed
      if (!Array.isArray(nextFeed.features)) throw new Error('Unexpected USGS response')
      setFeed(nextFeed)
      cacheFeed(range, nextFeed)
    } catch (fetchError) {
      if (fetchError instanceof DOMException && fetchError.name === 'AbortError') return
      const cached = loadCachedFeed(range)
      if (cached) setFeed(cached)
      setError(cached ? 'Live refresh failed. Showing the most recent saved USGS data.' : 'Live USGS data could not be loaded. Check your connection and try again.')
    } finally {
      if (!controller.signal.aborted) {
        setLoading(false)
        setRefreshing(false)
      }
    }
  }, [])

  useEffect(() => {
    fetchData(filters.range)
    setVisibleRows(120)
    return () => abortRef.current?.abort()
  }, [filters.range, fetchData])

  useEffect(() => {
    const interval = window.setInterval(() => setClock(Date.now()), 30_000)
    const online = () => { setOffline(false); fetchData(filters.range, Boolean(feed)) }
    const offlineHandler = () => setOffline(true)
    window.addEventListener('online', online)
    window.addEventListener('offline', offlineHandler)
    return () => {
      window.clearInterval(interval)
      window.removeEventListener('online', online)
      window.removeEventListener('offline', offlineHandler)
    }
  }, [feed, filters.range, fetchData])

  useEffect(() => writeUrlState(filters, selectedId), [filters, selectedId])

  const filteredEvents = useMemo(() => filterEvents(feed?.features ?? [], filters, bounds), [feed, filters, bounds])
  const selectedEvent = useMemo(() => (feed?.features ?? []).find((event) => event.id === selectedId) ?? null, [feed, selectedId])
  const strongest = useMemo(() => [...filteredEvents].sort((a, b) => (b.properties.mag ?? -10) - (a.properties.mag ?? -10))[0] ?? null, [filteredEvents])
  const recentCount = filteredEvents.filter((event) => clock - event.properties.time <= 24 * 60 * 60 * 1000).length
  const oldestHalf = filteredEvents.filter((event) => event.properties.time < clock - ({ hour: 30, day: 12 * 60, week: 3.5 * 24 * 60, month: 15 * 24 * 60 }[filters.range]) * 60_000).length
  const newerHalf = filteredEvents.length - oldestHalf
  const trend = oldestHalf === 0 ? null : Math.round(((newerHalf - oldestHalf) / oldestHalf) * 100)
  const activeFilterCount = [filters.minMagnitude !== DEFAULT_FILTERS.minMagnitude, filters.depth !== 'all', filters.alert !== 'all', filters.tsunami !== 'all', filters.status !== 'all', Boolean(filters.query), filters.area !== 'world'].filter(Boolean).length
  const staleMinutes = feed ? Math.max(0, Math.floor((clock - feed.metadata.generated) / 60_000)) : 0
  const isStale = staleMinutes > 30

  const selectEvent = useCallback((event: EarthquakeFeature) => {
    setSelectedId(event.id)
    setMobileView('map')
  }, [])
  const updateBounds = useCallback((nextBounds: MapBounds) => setBounds(nextBounds), [])
  const updateHighlight = useCallback((ids: Set<string> | null) => setHighlightedIds(ids), [])

  const share = async () => {
    const shareData = { title: selectedEvent?.properties.title ?? 'Seismic Field', text: selectedEvent ? `${selectedEvent.properties.title} on Seismic Field` : `Explore ${filteredEvents.length} recent earthquakes on Seismic Field`, url: window.location.href }
    try {
      if (navigator.share) await navigator.share(shareData)
      else {
        await navigator.clipboard.writeText(window.location.href)
        setCopied(true)
        window.setTimeout(() => setCopied(false), 2000)
      }
    } catch {
      // Sharing can be dismissed without changing the exploration state.
    }
  }

  return (
    <div className="app-shell">
      <header className="site-header">
        <a className="brand" href="/" aria-label="Seismic Field home"><span className="brand-mark"><i /><i /><i /></span><span><strong>Seismic Field</strong><small>Live earthquake observatory</small></span></a>
        <TimeTabs value={filters.range} onChange={(range) => setFilters(updateFilter(filters, 'range', range))} />
        <div className="header-actions">
          <button className="header-button" type="button" onClick={() => fetchData(filters.range, Boolean(feed))} disabled={refreshing}><RefreshCw className={refreshing ? 'is-spinning' : ''} /><span>{refreshing ? 'Refreshing' : 'Refresh'}</span></button>
          <button className="header-button" type="button" onClick={share}><Share2 /><span>{copied ? 'Link copied' : 'Share'}</span></button>
        </div>
      </header>

      <div className="data-status" role="status" aria-live="polite">
        <span className={error || offline || isStale ? 'status-dot is-warning' : 'status-dot'} />
        {loading && !feed ? 'Connecting to the USGS live feed…' : error ?? (offline ? `Offline · showing data generated ${formatRelativeTime(feed?.metadata.generated ?? clock, clock)}` : `USGS feed generated ${formatRelativeTime(feed?.metadata.generated ?? clock, clock)}${isStale ? ' · data may be stale' : ''}`)}
        <span>Earthquake records may be revised.</span>
        {(error || offline || isStale) && <button type="button" onClick={() => fetchData(filters.range, Boolean(feed))}>Try live refresh</button>}
      </div>

      <main>
        <section className="observation-header" aria-labelledby="page-title">
          <div className="observation-copy">
            <p className="eyebrow">Global field · {RANGE_LABELS[filters.range]}</p>
            <h1 id="page-title">The ground in motion, <em>right now.</em></h1>
            <p>Explore verified and automatic earthquake records as they arrive. Select any signal to connect its place, time, depth, and significance.</p>
          </div>
          <div className="field-summary" aria-label="Current activity summary">
            <div><small>In view</small><strong>{filteredEvents.length.toLocaleString()}</strong><span>of {(feed?.features.length ?? 0).toLocaleString()} loaded</span></div>
            <div><small>Past 24 hours</small><strong>{recentCount.toLocaleString()}</strong><span>matching events</span></div>
            <div className="strongest-summary"><small>Strongest in view</small>{strongest ? <button type="button" onClick={() => selectEvent(strongest)}><strong>M{formatMagnitude(strongest.properties.mag)}</strong><span>{strongest.properties.place ?? 'Location pending'}</span></button> : <strong>—</strong>}</div>
            <div><small>Activity balance</small><strong>{trend == null ? '—' : `${trend > 0 ? '+' : ''}${trend}%`}</strong><span>newer vs earlier half</span></div>
          </div>
        </section>

        <Timeline events={filteredEvents} range={filters.range} selectedEvent={selectedEvent} onHighlight={updateHighlight} />

        <div className="mobile-view-switch" aria-label="Choose primary view">
          <button type="button" className={mobileView === 'map' ? 'is-active' : ''} onClick={() => setMobileView('map')}><MapIcon /> Map</button>
          <button type="button" className={mobileView === 'list' ? 'is-active' : ''} onClick={() => setMobileView('list')}><List /> Events <span>{filteredEvents.length}</span></button>
        </div>

        <section className="explorer" aria-label="Earthquake explorer">
          <aside className="filters-column">
            <FilterPanel filters={filters} onChange={setFilters} resultCount={filteredEvents.length} totalCount={feed?.features.length ?? 0} />
            <div className="source-note"><ShieldCheck /><p><strong>Public information, not an alert service.</strong> Data comes from the USGS and can change. For urgent guidance, follow local authorities.</p></div>
          </aside>

          <div className={`map-column ${mobileView === 'map' ? 'is-mobile-active' : ''}`}>
            <div className="map-toolbar">
              <button type="button" onClick={() => setFiltersOpen(true)}><Filter /> Filters {activeFilterCount > 0 && <span>{activeFilterCount}</span>}</button>
              <button type="button" onClick={() => setFitSignal((value) => value + 1)} disabled={filteredEvents.length === 0}><LocateFixed /> Fit results</button>
              <button type="button" className={filters.area === 'viewport' ? 'is-active' : ''} aria-pressed={filters.area === 'viewport'} onClick={() => setFilters(updateFilter(filters, 'area', filters.area === 'viewport' ? 'world' : 'viewport'))}><Crosshair /> Visible area</button>
            </div>
            {loading && !feed ? <div className="map-loading" aria-label="Loading map data"><div className="contour-loader"><i /><i /><i /></div><strong>Reading the seismic field</strong><span>Connecting to live USGS observations…</span></div> : filteredEvents.length === 0 ? <div className="empty-map"><Layers3 /><h2>No signals match this field</h2><p>These constraints exclude all loaded events. Clear filters or expand the map area to recover the view.</p><button type="button" onClick={() => setFilters({ ...DEFAULT_FILTERS, range: filters.range })}>Reset filters</button></div> : <MapView events={filteredEvents} selectedId={selectedId} highlightedIds={highlightedIds} onSelect={selectEvent} onHover={setHoveredId} hoveredId={hoveredId} onBoundsChange={updateBounds} fitSignal={fitSignal} />}
          </div>

          <section id="event-stream" className={`stream-column ${mobileView === 'list' ? 'is-mobile-active' : ''}`} aria-labelledby="stream-title">
            <div className="stream-heading">
              <div><p className="eyebrow">Synchronized event stream</p><h2 id="stream-title">{filteredEvents.length.toLocaleString()} signals</h2></div>
              <label>Sort <select value={filters.sort} onChange={(event) => setFilters(updateFilter(filters, 'sort', event.target.value as FilterState['sort']))}><option value="significance">Significance</option><option value="magnitude">Magnitude</option><option value="newest">Newest</option><option value="depth">Deepest</option></select></label>
            </div>
            <ActiveFilters filters={filters} onChange={setFilters} />
            {loading && !feed ? <ul className="event-skeleton" aria-label="Loading events">{Array.from({ length: 8 }, (_, index) => <li key={index}><i /><span /><span /></li>)}</ul> : error && !feed ? <div className="stream-empty"><AlertTriangle /><h3>USGS data is unavailable</h3><p>No fictional or sample events are being shown. Retry when your connection is available.</p><button type="button" onClick={() => fetchData(filters.range)}>Retry</button></div> : filteredEvents.length === 0 ? <div className="stream-empty"><Search /><h3>No matching events</h3><p>Try a lower magnitude, a wider depth range, or the whole-world area.</p><button type="button" onClick={() => setFilters({ ...DEFAULT_FILTERS, range: filters.range })}>Reset filters</button></div> : <><ol className="event-list">{filteredEvents.slice(0, visibleRows).map((event) => <EventRow key={event.id} event={event} selected={event.id === selectedId} highlighted={!highlightedIds || highlightedIds.has(event.id)} onSelect={() => selectEvent(event)} onHover={setHoveredId} />)}</ol>{visibleRows < filteredEvents.length && <button className="load-more" type="button" onClick={() => setVisibleRows((count) => count + 150)}>Show 150 more <ChevronDown /></button>}</>}
          </section>

          {selectedEvent && <EventDetail event={selectedEvent} allEvents={filteredEvents.length ? filteredEvents : feed?.features ?? []} onClose={() => setSelectedId(null)} />}
        </section>
      </main>

      {filtersOpen && <div className="sheet-backdrop" onMouseDown={(event) => { if (event.currentTarget === event.target) setFiltersOpen(false) }}><div className="filter-sheet" role="dialog" aria-modal="true" aria-label="Earthquake filters"><FilterPanel filters={filters} onChange={setFilters} resultCount={filteredEvents.length} totalCount={feed?.features.length ?? 0} onClose={() => setFiltersOpen(false)} /><button className="apply-filters" type="button" onClick={() => setFiltersOpen(false)}>View {filteredEvents.length.toLocaleString()} events</button></div></div>}

      <footer><p>Data: <a href="https://earthquake.usgs.gov/earthquakes/feed/" target="_blank" rel="noreferrer">U.S. Geological Survey <ArrowUpRight /></a> · Basemap: OpenStreetMap contributors</p><p>Seismic Field does not predict earthquakes or guarantee safety.</p></footer>
      <div className="sr-only" aria-live="polite">{selectedEvent ? `Selected ${selectedEvent.properties.title}` : ''}</div>
    </div>
  )
}

