  .event-detail { position: fixed; inset: 0; z-index: 2500; width: 100%; height: 100%; padding: 18px 18px 34px; border: 0; animation: detail-up .22s ease-out; }
  @keyframes detail-up { from { opacity: 0; transform: translateY(28px); } }
  .detail-hero { grid-template-columns: 86px 1fr; gap: 14px; }
  .detail-magnitude { width: 82px; height: 82px; }
